# --- Language Preference Functions ---
def _update_language_json(mutator):
    """Atomically update the shared Language.json preferences file."""
    try:
        data = {}
        if os.path.exists(LANGUAGE_JSON_PATH):
            try:
                with open(LANGUAGE_JSON_PATH, "r", encoding="utf-8") as handle:
                    loaded = json.load(handle)
                    if isinstance(loaded, dict):
                        data = loaded
            except Exception:
                data = {}
        mutator(data)
        parent = os.path.dirname(LANGUAGE_JSON_PATH) or HOME_DIR
        os.makedirs(parent, exist_ok=True)
        temp = LANGUAGE_JSON_PATH + f".tmp-{os.getpid()}-{threading.get_ident()}"
        try:
            with open(temp, "w", encoding="utf-8") as handle:
                json.dump(data, handle, ensure_ascii=False, indent=4)
                handle.flush()
                os.fsync(handle.fileno())
            os.chmod(temp, 0o600)
            os.replace(temp, LANGUAGE_JSON_PATH)
        finally:
            try:
                if os.path.exists(temp):
                    os.remove(temp)
            except OSError:
                pass
        return True
    except Exception:
        return False


def save_language_preference(language):
    """Saves the selected language to a persistent JSON file."""
    return _update_language_json(lambda data: data.__setitem__('preferred_language', language))

def load_language_preference():
    """Loads the preferred language from the persistent JSON file."""
    if os.path.exists(LANGUAGE_JSON_PATH):
        try:
            with open(LANGUAGE_JSON_PATH, "r") as f:
                data = json.load(f)
                return data.get('preferred_language')
        except Exception:
            return None
    return None


# --- Persistent Menu Autostart Config ---
# Stored in the same Language.json for simplicity/backwards-compatibility.
def save_menu_autostart_preference(enabled: bool):
    """Saves whether the menu should auto-start when Termux opens."""
    return _update_language_json(lambda data: data.__setitem__('menu_autostart', bool(enabled)))

def load_menu_autostart_preference() -> bool:
    """Loads the menu auto-start preference. Defaults to True."""
    if os.path.exists(LANGUAGE_JSON_PATH):
        try:
            with open(LANGUAGE_JSON_PATH, "r") as f:
                data = json.load(f)
                return bool(data.get('menu_autostart', True))
        except Exception:
            return True
    return True


def save_menu_style_preference(style):
    """Persists the selected main-menu style independently of bash.bashrc."""
    valid = {"list", "grid", "number", "pipboy", "dedsec_os"}
    if style not in valid:
        return False
    return _update_language_json(lambda data: data.__setitem__('menu_style', style))


def load_menu_style_preference():
    """Returns a valid saved menu style, or None for legacy installations."""
    try:
        with open(LANGUAGE_JSON_PATH, "r", encoding="utf-8") as handle:
            style = json.load(handle).get("menu_style")
        if style in {"list", "grid", "number", "pipboy", "dedsec_os"}:
            return style
    except Exception:
        pass
    return None

def enforce_language_folder_visibility():
    """
    Checks the saved language preference and ensures the Greek folder 
    is hidden or visible accordingly before the menu starts.
    """
    preferred_language = load_language_preference()
    
    if preferred_language == 'english':
        # If English is preferred, ensure Greek folder is HIDDEN
        if os.path.isdir(GREEK_PATH_FULL):
            try:
                os.rename(GREEK_PATH_FULL, HIDDEN_GREEK_PATH)
            except OSError:
                pass
    elif preferred_language == 'greek':
        # If Greek is preferred, ensure Greek folder is VISIBLE
        if os.path.isdir(HIDDEN_GREEK_PATH):
            try:
                os.rename(HIDDEN_GREEK_PATH, GREEK_PATH_FULL)
            except OSError:
                pass

