# ------------------------------
# Translation Helpers
# ------------------------------
def get_current_language_path():
    """Detects the currently configured DedSec language path from bash.bashrc."""
    try:
        with open(BASHRC_PATH, "r") as f:
            lines = f.readlines()
    except Exception:
        return ENGLISH_BASE_PATH  # Default

    start_marker = BASHRC_START_MARKER
    end_marker = BASHRC_END_MARKER
    in_block = False

    for line in lines:
        if start_marker in line:
            in_block = True
            continue
        if end_marker in line:
            in_block = False
            break

        # Works for both the startup line and alias lines like: alias e='cd "..." && python3 ...'
        if in_block:
            match = re.search(r'cd\s+\"([^\"]+)\"', line)
            if match:
                return match.group(1).strip()

    return ENGLISH_BASE_PATH  # Default

def get_current_display_language():
    global CURRENT_DISPLAY_LANGUAGE
    lang_from_json = load_language_preference()
    if lang_from_json in ['english', 'greek']:
        CURRENT_DISPLAY_LANGUAGE = lang_from_json
        return CURRENT_DISPLAY_LANGUAGE
    
    current_path = get_current_language_path()
    CURRENT_DISPLAY_LANGUAGE = LANGUAGE_MAP.get(current_path, 'english')
    return CURRENT_DISPLAY_LANGUAGE

def _(text):
    current_lang = get_current_display_language() 
    if current_lang == 'greek':
        return GREEK_STRINGS.get(text, text)
    return text


def safe_curses_addstr(stdscr, y, x, text, attr=0):
    """Draws curses text safely on small/mobile terminal sizes."""
    try:
        height, width = stdscr.getmaxyx()
        if y < 0 or y >= height or width <= 0:
            return
        x = max(0, x)
        if x >= width:
            return
        safe_text = str(text)[:max(0, width - x - 1)]
        if not safe_text:
            return
        if attr:
            stdscr.addstr(y, x, safe_text, attr)
        else:
            stdscr.addstr(y, x, safe_text)
    except Exception:
        pass


def safe_curses_wrapper(func, *args, **kwargs):
    """Run a curses UI while tolerating Termux cleanup-only errors.

    Startup deliberately matches :func:`curses.wrapper`: ``noecho()``,
    ``cbreak()`` and keypad mode must all succeed before the UI starts. Hiding
    failures there leaves the terminal in canonical/echo mode, causing arrow
    keys to appear as escape text such as ``^[OB`` and requiring Enter.

    Some Termux/Python 3.14 combinations raise ``curses.error`` only while
    restoring the terminal after the UI has already returned. Those cleanup
    operations are best-effort so a valid menu result is not discarded.
    """
    stdscr = None
    try:
        stdscr = curses.initscr()
        # Keep the original curses.wrapper startup semantics. Do not suppress
        # these errors; the menu must never run with echo/canonical input active.
        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
        return func(stdscr, *args, **kwargs)
    finally:
        if stdscr is not None:
            # Restore in the same logical order as curses.wrapper. Cleanup can
            # return ERR on Termux even when the UI completed successfully.
            cleanup_steps = (
                lambda: stdscr.keypad(False),
                curses.echo,
                curses.nocbreak,
                curses.endwin,
            )
            for cleanup in cleanup_steps:
                try:
                    cleanup()
                except curses.error:
                    pass

