# --- File Type Detection Helper ---
def get_file_icon(filename, full_path):
    """Returns the appropriate icon for a file based on its type."""
    if os.path.isdir(full_path):
        return FOLDER_ICON
    
    if filename.endswith('.py'):
        return PYTHON_ICON
    elif filename.endswith('.js') or filename.endswith('.javascript'):
        return JAVASCRIPT_ICON
    elif filename.endswith('.sh') or filename.endswith('.bash'):
        return SHELL_ICON
    elif os.access(full_path, os.X_OK):
        return EXECUTABLE_ICON
    else:
        return GENERIC_SCRIPT_ICON

def format_display_name(filename, full_path):
    """Formats the display name with icons - only at the start."""
    icon = get_file_icon(filename, full_path)
    return f"{icon} {filename}"

def get_sponsor_tier_config(tier_key):
    """Returns the sponsor tier configuration for 3, 9, or 25."""
    tier_key = str(tier_key or "").replace("$", "").strip()
    return SPONSORS_TIERS.get(tier_key)


def get_sponsors_tier_root_path(tier_key):
    """Returns the Termux home folder path for a sponsor tier."""
    config = get_sponsor_tier_config(tier_key)
    if not config:
        return None
    return os.path.join(HOME_DIR, config["root_name"])


def get_sponsors_display_entries():
    """Returns visible Sponsors-Only folders as menu entries."""
    entries = []
    for tier_key in SPONSORS_TIER_ORDER:
        config = get_sponsor_tier_config(tier_key)
        root_path = get_sponsors_tier_root_path(tier_key)
        if config and root_path and os.path.isdir(root_path):
            entries.append((format_display_name(config["root_name"], root_path), f"go_sponsors:{tier_key}"))
    return entries


def get_sponsors_display_name():
    """Backwards-compatible single Sponsors-Only label for older code paths."""
    entries = get_sponsors_display_entries()
    return entries[0][0] if entries else None


def get_sponsors_go_token_for_display_name(display_name):
    """Maps a visible Sponsors-Only menu label back to its tier navigation token."""
    for label, go_token in get_sponsors_display_entries():
        if display_name == label:
            return go_token
    return None


def get_sponsors_existing_root_paths():
    """Returns all downloaded Sponsors-Only tier root folders."""
    paths = []
    for tier_key in SPONSORS_TIER_ORDER:
        root_path = get_sponsors_tier_root_path(tier_key)
        if root_path and os.path.isdir(root_path):
            paths.append(root_path)
    return paths


def get_sponsors_preferred_path(tier_key=None):
    """Returns the preferred Sponsors-Only language path, with safe fallbacks."""
    if tier_key is None:
        for candidate_tier in SPONSORS_TIER_ORDER:
            candidate_root = get_sponsors_tier_root_path(candidate_tier)
            if candidate_root and os.path.isdir(candidate_root):
                tier_key = candidate_tier
                break

    config = get_sponsor_tier_config(tier_key)
    root_path = get_sponsors_tier_root_path(tier_key)
    if not config or not root_path or not os.path.isdir(root_path):
        return None

    preferred_language = load_language_preference()
    if preferred_language not in ['english', 'greek']:
        preferred_language = get_current_display_language()

    preferred_folder = (
        SPONSORS_ENGLISH_FOLDER_NAME
        if preferred_language == 'english'
        else SPONSORS_GREEK_FOLDER_NAME
    )
    preferred_path = os.path.join(root_path, preferred_folder)
    if os.path.isdir(preferred_path):
        return preferred_path

    fallback_folder = (
        SPONSORS_GREEK_FOLDER_NAME
        if preferred_folder == SPONSORS_ENGLISH_FOLDER_NAME
        else SPONSORS_ENGLISH_FOLDER_NAME
    )
    fallback_path = os.path.join(root_path, fallback_folder)
    if os.path.isdir(fallback_path):
        return fallback_path

    return root_path

# --- Utility Functions ---

def clear_terminal_screen():
    """Clear an interactive terminal without spawning a shell process."""
    try:
        sys.stdout.write("\033[2J\033[H")
        sys.stdout.flush()
    except Exception:
        pass

def _command_argv(command):
    if isinstance(command, (list, tuple)):
        return [str(item) for item in command]
    return shlex.split(str(command or ""))


def run_command(command, cwd=None):
    """Run a command without an implicit shell."""
    argv = _command_argv(command)
    if not argv:
        raise ValueError("Command is empty.")
    return subprocess.run(argv, cwd=cwd, capture_output=False, text=True, check=False)


def run_command_silent(command, cwd=None):
    argv = _command_argv(command)
    if not argv:
        return "", "Command is empty."
    result = subprocess.run(argv, cwd=cwd, capture_output=True, text=True, check=False)
    return result.stdout.strip(), result.stderr.strip()



def run_selected_file(abs_path):
    """Runs a selected script/executable reliably (works with nested folders & spaces)."""
    try:
        abs_path = os.path.abspath(abs_path)
        if not os.path.isfile(abs_path):
            return None

        workdir = os.path.dirname(abs_path) or os.getcwd()

        # Decide how to run it
        if abs_path.endswith(".py"):
            cmd = ["python3", abs_path]
        elif abs_path.endswith(".sh") or abs_path.endswith(".bash"):
            cmd = ["bash", abs_path]
        elif os.access(abs_path, os.X_OK):
            cmd = [abs_path]
        else:
            return None

        proc = subprocess.run(cmd, cwd=workdir)
        return proc.returncode
    except KeyboardInterrupt:
        return 130

def get_termux_info():
    if shutil.which("termux-info"):
        out, _err = run_command_silent("termux-info -j")
        try:
            info = json.loads(out)
            termux_version = info.get("termux_version", info.get("app_version", "Unknown"))
            termux_api_version = info.get("termux_api_version", "Unknown")
        except Exception:
            termux_version = "Unknown"
            termux_api_version = "Unknown"
    else:
        termux_version = "Unknown"
        termux_api_version = "Unknown"
    termux_style_version = "Default"
    return termux_version, termux_api_version, termux_style_version

def get_latest_dedsec_update(path):
    if path and os.path.isdir(path):
        stdout, _err = run_command_silent("git log -1 --format=%cd", cwd=path)
        return stdout if stdout else _("Not available")
    return _("DedSec directory not found")

def find_dedsec():
    """Locate DedSec without recursively scanning all of shared storage."""
    candidates = [
        os.path.join(HOME_DIR, "DedSec"),
        os.path.dirname(ENGLISH_BASE_PATH),
        os.path.dirname(os.path.dirname(os.path.realpath(__file__))),
    ]
    for candidate in candidates:
        candidate = os.path.realpath(candidate)
        if os.path.isdir(candidate) and (
            os.path.isdir(os.path.join(candidate, "Scripts"))
            or os.path.isfile(os.path.join(candidate, "Setup.sh"))
            or os.path.isfile(os.path.join(candidate, "README.md"))
        ):
            return candidate
    try:
        for entry in os.scandir(HOME_DIR):
            if entry.is_dir(follow_symlinks=False) and entry.name.casefold() == "dedsec":
                return os.path.realpath(entry.path)
    except OSError:
        pass
    return None

def get_github_repo_size(repo_api_url):
    try:
        response = requests.get(repo_api_url, timeout=20)
        if response.status_code == 200:
            size_kb = response.json().get('size', 0)
            return f"{size_kb / 1024:.2f} MB"
    except Exception:
        pass
    return _("Unable to fetch repository size")

def _du_human_size(path):
    """Return a human-readable du size without shell interpolation."""
    try:
        result = subprocess.run(
            ["du", "-sh", os.path.abspath(os.path.expanduser(str(path)))],
            capture_output=True, text=True, timeout=30, check=False,
        )
        if result.returncode == 0 and result.stdout.strip():
            return result.stdout.split()[0]
    except Exception:
        pass
    return "Unknown"

def get_termux_size():
    termux_root = "/data/data/com.termux"
    if os.path.exists(termux_root):
        return _du_human_size(termux_root)
    return _du_human_size(os.environ.get("HOME", "~"))

def get_dedsec_size(path):
    if path and os.path.isdir(path):
        return _du_human_size(path)
    return _("DedSec directory not found")

def clone_repo(repo_url):
    print(f"[+] DedSec not found. {_('Cloning repository...')}")
    git = shutil.which("git") or "git"
    destination = os.path.join(os.getcwd(), LOCAL_DIR)
    result = subprocess.run([git, "clone", str(repo_url), destination], check=False, timeout=GIT_OPERATION_TIMEOUT)
    if result.returncode != 0 or not os.path.isdir(destination):
        raise RuntimeError(f"git clone failed with exit code {result.returncode}")
    return destination

def git_remote_default_branch(repo_url, cwd=None):
    """Return the remote default branch without assuming it is named main."""
    git = shutil.which("git") or "git"
    try:
        result = subprocess.run(
            [git, "ls-remote", "--symref", repo_url, "HEAD"],
            cwd=cwd, capture_output=True, text=True,
            timeout=PIPBOY_REMOTE_CHECK_TIMEOUT, check=False,
        )
        for line in (result.stdout or "").splitlines():
            match = re.match(r"ref:\s+refs/heads/([^\s]+)\s+HEAD$", line.strip())
            if match:
                return match.group(1)
    except Exception:
        pass
    if cwd:
        try:
            output, _error = run_command_silent("git symbolic-ref --short refs/remotes/origin/HEAD", cwd=cwd)
            if output:
                return output.strip().split("/")[-1]
        except Exception:
            pass
    return "main"


def force_update_repo(existing_path, repo_url):
    if not existing_path:
        return False
    print(f"[+] DedSec found! {_('Forcing a full update...')}")
    branch = git_remote_default_branch(repo_url, cwd=existing_path)
    remote = subprocess.run(
        [shutil.which("git") or "git", "remote", "set-url", "origin", repo_url],
        cwd=existing_path, check=False, timeout=30,
    )
    if remote.returncode != 0:
        raise RuntimeError("git remote set-url failed")
    fetch = subprocess.run(
        [shutil.which("git") or "git", "fetch", "--prune", "origin", branch],
        cwd=existing_path, check=False, timeout=GIT_OPERATION_TIMEOUT,
    )
    if fetch.returncode != 0:
        raise RuntimeError(f"git fetch failed for origin/{branch}")
    reset = subprocess.run(
        [shutil.which("git") or "git", "reset", "--hard", f"origin/{branch}"],
        cwd=existing_path, check=False, timeout=120,
    )
    if reset.returncode != 0:
        raise RuntimeError(f"git reset failed for origin/{branch}")
    subprocess.run(
        [shutil.which("git") or "git", "clean", "-f", "--", "*.py", "*.css", "*.sh", "*.bash"],
        cwd=existing_path, check=False, timeout=60,
    )
    print(_("Repository fully updated, including README and all other files."))
    return True


def update_dedsec(repo_url=REPO_URL_SOURCE_1, repo_api_url=REPO_API_URL_SOURCE_1):
    repo_size = get_github_repo_size(repo_api_url)
    print(f"[+] {_('GitHub repository size')}: {repo_size}")
    existing_dedsec_path = find_dedsec()
    update_changed = False
    update_error = None
    try:
        if existing_dedsec_path:
            branch = git_remote_default_branch(repo_url, cwd=existing_dedsec_path)
            subprocess.run(
                [shutil.which("git") or "git", "remote", "set-url", "origin", repo_url],
                cwd=existing_dedsec_path, check=False, timeout=30,
            )
            fetch = subprocess.run(
                [shutil.which("git") or "git", "fetch", "--prune", "origin", branch],
                cwd=existing_dedsec_path, capture_output=True, text=True, check=False, timeout=GIT_OPERATION_TIMEOUT,
            )
            if fetch.returncode != 0:
                raise RuntimeError((fetch.stderr or fetch.stdout or "git fetch failed").strip())
            behind_result = subprocess.run(
                [shutil.which("git") or "git", "rev-list", f"HEAD..origin/{branch}", "--count"],
                cwd=existing_dedsec_path, capture_output=True, text=True, check=False, timeout=60,
            )
            if behind_result.returncode != 0:
                raise RuntimeError((behind_result.stderr or behind_result.stdout or "git rev-list failed").strip())
            behind_text = behind_result.stdout.strip()
            try:
                behind_count = int(behind_text or 0)
            except (TypeError, ValueError) as exc:
                raise RuntimeError("git rev-list returned an invalid update count") from exc
            if behind_count > 0:
                update_changed = bool(force_update_repo(existing_dedsec_path, repo_url))
                dedsec_size = get_dedsec_size(existing_dedsec_path)
                print(f"[+] {_('Update applied. DedSec Project Size')}: {dedsec_size}")
            else:
                print(_("No available update found."))
        else:
            existing_dedsec_path = clone_repo(repo_url)
            update_changed = True
            dedsec_size = get_dedsec_size(existing_dedsec_path)
            print(f"[+] {_('Cloned new DedSec repository. DedSec Project Size')}: {dedsec_size}")
    except Exception as exc:
        update_error = exc
        raise
    finally:
        # The knowledge check runs after every press of either project-update
        # option, even when the Git update itself fails partway through.
        try:
            pipboy_refresh_knowledge_after_update(
                trigger="dedsec_source_1" if repo_url == REPO_URL_SOURCE_1 else "dedsec_source_2",
                force_project_rebuild=update_changed,
                quiet=False,
            )
        except Exception as refresh_exc:
            try:
                pipboy_log_error("post-update knowledge refresh", refresh_exc)
            except Exception:
                pass
            print(pipboy_text(
                f"[!] Ded-Guy knowledge refresh failed after the update attempt: {refresh_exc}",
                f"[!] Η ανανέωση γνώσης Ded-Guy απέτυχε μετά την προσπάθεια ενημέρωσης: {refresh_exc}",
            ))
            if update_error is None:
                # The project update succeeded, so database-refresh failure is
                # reported without pretending the project update itself failed.
                pass

    # Keep the final success notice at the actual end of the complete update
    # workflow, after the repository and Ded-Guy knowledge refresh have both
    # finished. If a validated Settings candidate exists, immediately show the
    # exact installation command instead of waiting for the next Termux launch.
    print(f"[+] {_('Update process completed successfully')}!")
    install_notice = dedguy_post_update_install_notice()
    if install_notice:
        print(install_notice)
    return existing_dedsec_path


def update_dedsec_source_1():
    return update_dedsec(REPO_URL_SOURCE_1, REPO_API_URL_SOURCE_1)


def update_dedsec_source_2():
    return update_dedsec(REPO_URL_SOURCE_2, REPO_API_URL_SOURCE_2)

def get_internal_storage():
    df_out, _err = run_command_silent("df -h /data")
    lines = df_out.splitlines()
    if len(lines) >= 2:
        fields = lines[1].split()
        return fields[1]
    return "Unknown"

def get_processor_info():
    cpuinfo, _err = run_command_silent("cat /proc/cpuinfo")
    for line in cpuinfo.splitlines():
        if "Hardware" in line:
            return line.split(":", 1)[1].strip()
        if "Processor" in line:
            return line.split(":", 1)[1].strip()
    return "Unknown"

def get_ram_info():
    try:
        meminfo, _err = run_command_silent("cat /proc/meminfo")
        for line in meminfo.splitlines():
            if "MemTotal" in line:
                parts = line.split()
                if len(parts) >= 2:
                    mem_total_kb = parts[1]
                    try:
                        mem_mb = int(mem_total_kb) / 1024
                        return f"{mem_mb:.2f} MB"
                    except Exception:
                        return parts[1] + " kB"
        return "Unknown"
    except Exception:
        return "Unknown"

def get_carrier():
    carrier, _err = run_command_silent("getprop gsm.operator.alpha")
    if not carrier:
        carrier, _err = run_command_silent("getprop ro.cdma.home.operator.alpha")
    return carrier if carrier else "Unknown"

def get_battery_info():
    if shutil.which("termux-battery-status"):
        out, _err = run_command_silent("termux-battery-status")
        try:
            info = json.loads(out)
            level = info.get("percentage", "Unknown")
            status = info.get("status", "Unknown")
            return f"{_('Battery')}: {level}% ({status})"
        except Exception:
            return f"{_('Battery')}: {_('Unknown')}"
    else:
        return f"{_('Battery')}: {_('Not available')}"

def get_hardware_details():
    internal_storage = get_internal_storage()
    processor = get_processor_info()
    ram = get_ram_info()
    carrier = get_carrier()
    kernel_version, _err = run_command_silent("uname -r")
    android_version, _err = run_command_silent("getprop ro.build.version.release")
    device_model, _err = run_command_silent("getprop ro.product.model")
    manufacturer, _err = run_command_silent("getprop ro.product.manufacturer")
    uptime, _err = run_command_silent("uptime -p")
    battery = get_battery_info()
    
    details = (
        f"{_('Internal Storage')}: {internal_storage}\n"
        f"{_('Processor')}: {processor}\n"
        f"{_('Ram')}: {ram}\n"
        f"{_('Carrier')}: {carrier}\n"
        f"{_('Kernel Version')}: {kernel_version}\n"
        f"{_('Android Version')}: {android_version}\n"
        f"{_('Device Model')}: {device_model}\n"
        f"{_('Manufacturer')}: {manufacturer}\n"
        f"{_('Uptime')}: {uptime}\n"
        f"{battery}"
    )
    return details

def get_user():
    output, _err = run_command_silent("whoami")
    return output if output else "Unknown"

def _remove_path_if_exists(target_path):
    """Removes a file/directory/symlink if it exists."""
    try:
        if os.path.islink(target_path) or os.path.isfile(target_path):
            os.remove(target_path)
        elif os.path.isdir(target_path):
            shutil.rmtree(target_path)
    except Exception:
        pass


def _download_file_silent(url, destination_path):
    headers = {"User-Agent": "Mozilla/5.0 (Termux; Android) DedSecProjectLegacySave/1.0"}
    with requests.get(url, stream=True, allow_redirects=True, timeout=120, headers=headers) as response:
        response.raise_for_status()
        with open(destination_path, "wb") as handle:
            for chunk in response.iter_content(chunk_size=1024 * 256):
                if chunk:
                    handle.write(chunk)


def _resolve_fdroid_package_apk_url(package_name):
    headers = {"User-Agent": "Mozilla/5.0 (Termux; Android) DedSecProjectLegacySave/1.0"}
    response = requests.get(f"https://f-droid.org/packages/{package_name}/", timeout=60, headers=headers)
    response.raise_for_status()
    html = response.text

    patterns = [
        r'href="([^"]+\.apk)"[^>]*>\s*Download APK',
        r'href="([^"]*' + re.escape(package_name) + r'[^"]*\.apk)"',
        r'href="([^"]+\.apk)"',
    ]

    for pattern in patterns:
        match = re.search(pattern, html, re.IGNORECASE | re.DOTALL)
        if match:
            apk_url = match.group(1).strip()
            if apk_url.startswith("//"):
                return "https:" + apk_url
            if apk_url.startswith("/"):
                return "https://f-droid.org" + apk_url
            if apk_url.startswith("http://") or apk_url.startswith("https://"):
                return apk_url
            return "https://f-droid.org/" + apk_url.lstrip("/")

    raise RuntimeError(f"Unable to resolve APK URL for {package_name}")


def _clone_repository_silent(repo_url, destination_path):
    _remove_path_if_exists(destination_path)
    result = subprocess.run(
        ["git", "clone", "--depth", "1", repo_url, destination_path],
        capture_output=True,
        text=True, timeout=GIT_OPERATION_TIMEOUT, check=False
    )
    if result.returncode != 0:
        error_message = (result.stderr or result.stdout or "git clone failed").strip()
        raise RuntimeError(error_message)

    git_dir = os.path.join(destination_path, ".git")
    if os.path.isdir(git_dir):
        shutil.rmtree(git_dir, ignore_errors=True)


def _project_save_github_identity(repo_url):
    """Return (owner, repository) for a normal github.com repository URL."""
    try:
        parsed = urlparse(str(repo_url or "").strip())
        if parsed.netloc.casefold() not in {"github.com", "www.github.com"}:
            return "", ""
        parts = [unquote(part) for part in parsed.path.strip("/").split("/") if part]
        if len(parts) < 2:
            return "", ""
        owner = parts[0]
        repository = parts[1]
        if repository.endswith(".git"):
            repository = repository[:-4]
        return owner, repository
    except Exception:
        return "", ""


def _project_save_repository_size_map(repo_sources):
    """Resolve GitHub repository sizes with at most one public API request per owner.

    GitHub's repository ``size`` value is used only to decide backup order. If a
    size cannot be resolved (offline, rate-limited, private, deleted, etc.), that
    repository remains eligible for backup and is placed after repositories with
    known sizes instead of being skipped.
    """
    wanted_by_owner = {}
    for repo_source in repo_sources:
        owner, repository = _project_save_github_identity(repo_source.get("url"))
        # The requested size ordering applies to the canonical dedsec1121fk
        # repositories. Legacy mirror repositories are kept as extra recovery
        # copies after the canonical size-ordered set, avoiding extra API calls.
        if owner.casefold() != "dedsec1121fk":
            continue
        if owner and repository:
            wanted_by_owner.setdefault(owner, set()).add(repository.casefold())

    size_map = {}
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": "DedSecProjectLegacySave/1.0 (Termux; Android)",
        "X-GitHub-Api-Version": "2022-11-28",
    }

    for owner, wanted_names in wanted_by_owner.items():
        remaining = set(wanted_names)
        # Usually one request per owner is enough. Additional pages are fetched
        # only when one of the required repositories was not on the first page.
        for page in range(1, 6):
            try:
                response = requests.get(
                    f"https://api.github.com/users/{quote(owner, safe='')}/repos",
                    params={"per_page": 100, "page": page, "type": "public", "sort": "full_name", "direction": "asc"},
                    headers=headers,
                    timeout=30,
                )
                response.raise_for_status()
                payload = response.json()
                if not isinstance(payload, list):
                    break
                for item in payload:
                    name = str(item.get("name") or "")
                    key = name.casefold()
                    if key in remaining:
                        try:
                            size_map[(owner.casefold(), key)] = max(0, int(item.get("size") or 0))
                        except Exception:
                            pass
                        remaining.discard(key)
                if not remaining or len(payload) < 100:
                    break
            except Exception as exc:
                pipboy_log_error(f"backup repository size lookup for {owner}", exc)
                break

    return size_map


def _ordered_project_save_repositories():
    """Return backup repositories ordered by current GitHub size, smallest first."""
    repo_sources = list(PROJECT_SAVE_REPOSITORIES)
    size_map = _project_save_repository_size_map(repo_sources)

    def sort_key(repo_source):
        owner, repository = _project_save_github_identity(repo_source.get("url"))
        size_kb = size_map.get((owner.casefold(), repository.casefold())) if owner and repository else None
        # Unknown-size repositories are still backed up, after known-size entries.
        return (
            size_kb is None,
            size_kb if size_kb is not None else float("inf"),
            str(repo_source.get("project_name") or repo_source.get("folder_name") or "").casefold(),
        )

    return sorted(repo_sources, key=sort_key), size_map


def _delete_existing_project_save_archives():
    archive_name = PROJECT_SAVE_ARCHIVE_NAME
    for current_root, _dirnames, filenames in os.walk(PROJECT_SAVE_SHARED_STORAGE_PATH, onerror=lambda _e: None):
        for filename in filenames:
            if filename == archive_name:
                _remove_path_if_exists(os.path.join(current_root, filename))


def _get_project_save_extra_copy_directories(max_count=PROJECT_SAVE_MAX_EXTRA_COPIES):
    extra_directories = []
    try:
        entries = sorted(os.listdir(PROJECT_SAVE_SHARED_STORAGE_PATH), key=str.lower)
    except Exception:
        return extra_directories

    for entry in entries:
        if entry.startswith('.') or entry in PROJECT_SAVE_EXCLUDED_TOP_LEVEL_DIRS:
            continue

        full_path = os.path.join(PROJECT_SAVE_SHARED_STORAGE_PATH, entry)
        if not os.path.isdir(full_path):
            continue

        extra_directories.append(full_path)
        if len(extra_directories) >= max_count:
            break

    return extra_directories



def _copy_project_archive_to_selected_folders(archive_path):
    for target_directory in _get_project_save_extra_copy_directories():
        target_path = os.path.join(target_directory, PROJECT_SAVE_ARCHIVE_NAME)
        try:
            shutil.copy2(archive_path, target_path)
        except Exception:
            pass



def _add_accessible_sponsor_repositories_to_project_save(repos_dir):
    """Checks both Sponsors-Only tiers and adds the ones the connected GitHub account can access."""
    status_lines = ["Sponsors-Only access check for DedSec Project Legacy Save:"]
    try:
        if not shutil.which("gh") or not github_auth_status():
            status_lines.append("- GitHub is not connected in gh, so sponsor repositories were not included.")
            status_path = os.path.join(repos_dir, "Sponsors-Only Access Status.txt")
            with open(status_path, "w", encoding="utf-8") as handle:
                handle.write("\n".join(status_lines) + "\n")
            return

        if not shutil.which("git") and not ensure_pkg_command("git", "git"):
            status_lines.append("- git is not available, so sponsor repositories were not included.")
            status_path = os.path.join(repos_dir, "Sponsors-Only Access Status.txt")
            with open(status_path, "w", encoding="utf-8") as handle:
                handle.write("\n".join(status_lines) + "\n")
            return

        token = github_token_for_sponsors()
        if not token:
            status_lines.append("- GitHub token could not be read, so sponsor repositories were not included.")
            status_path = os.path.join(repos_dir, "Sponsors-Only Access Status.txt")
            with open(status_path, "w", encoding="utf-8") as handle:
                handle.write("\n".join(status_lines) + "\n")
            return

        for tier_key in SPONSORS_TIER_ORDER:
            config = get_sponsor_tier_config(tier_key)
            if not config:
                continue

            rc, out = run_sponsors_git_command(["ls-remote", config["git_url"], "HEAD"], token)
            target_dir = os.path.join(repos_dir, config["root_name"])
            if rc == 0:
                _remove_path_if_exists(target_dir)
                clone_rc, clone_out = run_sponsors_git_command(
                    ["clone", "--depth", "1", config["git_url"], target_dir],
                    token
                )
                if clone_rc == 0 and os.path.isdir(target_dir):
                    git_dir = os.path.join(target_dir, ".git")
                    if os.path.isdir(git_dir):
                        shutil.rmtree(git_dir, ignore_errors=True)
                    status_lines.append(f"- {config['label']}: access confirmed and repository included.")
                else:
                    _remove_path_if_exists(target_dir)
                    status_lines.append(f"- {config['label']}: access confirmed, but clone failed.")
            else:
                message = (out or "no access").strip().splitlines()[-1]
                status_lines.append(f"- {config['label']}: no access or token approval required. ({message})")

    except Exception as error:
        status_lines.append("- Sponsor access check failed: " + str(error))

    status_path = os.path.join(repos_dir, "Sponsors-Only Access Status.txt")
    try:
        with open(status_path, "w", encoding="utf-8") as handle:
            handle.write("\n".join(status_lines) + "\n")
    except Exception:
        pass



def pipboy_log_error(context, error):
    """Append a recoverable error without hiding the original exception."""
    try:
        os.makedirs(os.path.dirname(PIPBOY_ERROR_LOG_PATH), exist_ok=True)
        stamp = time.strftime("%Y-%m-%d %H:%M:%S")
        with open(PIPBOY_ERROR_LOG_PATH, "a", encoding="utf-8") as handle:
            handle.write(f"[{stamp}] {context}: {error}\n")
    except Exception:
        pass


def _project_save_local_source(repo_source):
    """Return a local working copy when one is available, otherwise clone remote."""
    project_name = str(repo_source.get("project_name", ""))
    repo_url = str(repo_source.get("url", ""))
    folder_name = str(repo_source.get("folder_name", "")).strip()
    _owner, repository = _project_save_github_identity(repo_url)
    candidates = []

    # Generic candidates let every repository in PROJECT_SAVE_REPOSITORIES use
    # its current local working tree, not only projects known to Ded-Guy.
    for local_name in (folder_name, repository, f"{repository}-main" if repository else ""):
        if local_name:
            candidates.append(os.path.join(HOME_DIR, local_name))

    for project in PIPBOY_MANAGED_PROJECTS:
        if project_name == project.get("name") or repo_url.removesuffix(".git") == str(project.get("url", "")).removesuffix(".git"):
            candidates.extend(os.path.join(HOME_DIR, name) for name in project.get("local_names", []))
            candidates.append(os.path.join(PIPBOY_MANAGED_PROJECTS_DIR, project.get("key", "")))
    if project_name == "DedSec Project":
        candidates.extend([
            os.path.dirname(ENGLISH_BASE_PATH),
            os.path.dirname(os.path.dirname(os.path.realpath(__file__))),
        ])

    seen = set()
    for candidate in candidates:
        real = os.path.realpath(os.path.expanduser(candidate))
        if real in seen:
            continue
        seen.add(real)
        if os.path.isdir(real):
            return real
    return ""


def _copy_local_project_for_backup(source, destination):
    """Copy local project state while excluding Git metadata and Python caches."""
    _remove_path_if_exists(destination)
    shutil.copytree(
        source,
        destination,
        symlinks=True,
        ignore=shutil.ignore_patterns(".git", "__pycache__", "*.pyc", ".pytest_cache", ".mypy_cache"),
    )


def _write_project_backup_report(bundle_root, report_lines):
    report_path = os.path.join(bundle_root, "Backup Report.txt")
    with open(report_path, "w", encoding="utf-8") as handle:
        handle.write(pipboy_text("DedSec ecosystem backup report", "Αναφορά αντιγράφου ασφαλείας οικοσυστήματος DedSec") + "\n")
        handle.write("=" * 56 + "\n")
        handle.write("\n".join(report_lines).rstrip() + "\n")

def _build_project_save_archive(archive_path):
    """Create a recoverable multi-project backup and continue after item failures."""
    _remove_path_if_exists(PROJECT_SAVE_WORKDIR)
    os.makedirs(PROJECT_SAVE_WORKDIR, exist_ok=True)

    bundle_root = os.path.join(PROJECT_SAVE_WORKDIR, PROJECT_SAVE_BUNDLE_DIRNAME)
    apks_dir = os.path.join(bundle_root, "APKs")
    repos_dir = os.path.join(bundle_root, "Repositories")
    os.makedirs(apks_dir, exist_ok=True)
    os.makedirs(repos_dir, exist_ok=True)
    report_lines = [pipboy_text("Created: ", "Δημιουργήθηκε: ") + time.strftime('%Y-%m-%d %H:%M:%S'), ""]
    failures = 0

    report_lines.append(pipboy_text("APKs:", "APK αρχεία:"))
    for apk_source in PROJECT_SAVE_APK_SOURCES:
        target_path = os.path.join(apks_dir, apk_source["filename"])
        try:
            if apk_source["type"] == "direct":
                apk_url = apk_source["url"]
            else:
                apk_url = _resolve_fdroid_package_apk_url(apk_source["package"])
            _download_file_silent(apk_url, target_path)
            report_lines.append(pipboy_text("- INCLUDED: ", "- ΣΥΜΠΕΡΙΛΗΦΘΗΚΕ: ") + apk_source['filename'])
        except Exception as exc:
            failures += 1
            report_lines.append(pipboy_text("- FAILED: ", "- ΑΠΟΤΥΧΙΑ: ") + f"{apk_source['filename']} — {exc}")
            pipboy_log_error(f"backup APK {apk_source['filename']}", exc)

    report_lines.extend(["", pipboy_text("Repositories (smallest to largest):", "Αποθετήρια (από το μικρότερο στο μεγαλύτερο):")])
    ordered_repositories, repository_size_map = _ordered_project_save_repositories()
    for repo_source in ordered_repositories:
        repo_target_dir = os.path.join(repos_dir, repo_source["folder_name"])
        owner, repository = _project_save_github_identity(repo_source.get("url"))
        size_kb = repository_size_map.get((owner.casefold(), repository.casefold())) if owner and repository else None
        size_note = f" [{size_kb / 1024:.2f} MB]" if size_kb is not None else " [size unavailable]"
        local_source = _project_save_local_source(repo_source)
        try:
            if local_source:
                _copy_local_project_for_backup(local_source, repo_target_dir)
                report_lines.append(
                    pipboy_text("- INCLUDED LOCAL STATE: ", "- ΣΥΜΠΕΡΙΛΗΦΘΗΚΕ ΤΟΠΙΚΗ ΚΑΤΑΣΤΑΣΗ: ") + f"{repo_source['project_name']}{size_note} — {local_source}"
                )
            else:
                _clone_repository_silent(repo_source["url"], repo_target_dir)
                report_lines.append(
                    pipboy_text("- INCLUDED REMOTE SNAPSHOT: ", "- ΣΥΜΠΕΡΙΛΗΦΘΗΚΕ ΑΠΟΜΑΚΡΥΣΜΕΝΟ ΣΤΙΓΜΙΟΤΥΠΟ: ") + f"{repo_source['project_name']}{size_note} — {repo_source['url']}"
                )
        except Exception as exc:
            failures += 1
            _remove_path_if_exists(repo_target_dir)
            report_lines.append(pipboy_text("- FAILED: ", "- ΑΠΟΤΥΧΙΑ: ") + f"{repo_source['project_name']} — {exc}")
            pipboy_log_error(f"backup repository {repo_source['project_name']}", exc)

    try:
        _add_accessible_sponsor_repositories_to_project_save(repos_dir)
        report_lines.extend(["", pipboy_text("Sponsors-Only access status is stored inside the repositories folder.", "Η κατάσταση πρόσβασης Sponsors-Only αποθηκεύεται μέσα στον φάκελο αποθετηρίων.")])
    except Exception as exc:
        failures += 1
        report_lines.append(pipboy_text("- Sponsor repository check failed: ", "- Ο έλεγχος αποθετηρίων χορηγών απέτυχε: ") + str(exc))
        pipboy_log_error("backup sponsor repositories", exc)

    report_lines.extend(["", pipboy_text("Recoverable failures: ", "Ανακτήσιμες αποτυχίες: ") + str(failures)])
    _write_project_backup_report(bundle_root, report_lines)

    os.makedirs(os.path.dirname(archive_path), exist_ok=True)
    _remove_path_if_exists(archive_path)
    zip_failures = 0
    with zipfile.ZipFile(archive_path, "w", zipfile.ZIP_DEFLATED, allowZip64=True) as archive:
        for current_root, _dirnames, filenames in os.walk(bundle_root, onerror=lambda exc: pipboy_log_error("backup walk", exc)):
            for filename in filenames:
                full_path = os.path.join(current_root, filename)
                if os.path.islink(full_path):
                    continue
                relative_path = os.path.relpath(full_path, PROJECT_SAVE_WORKDIR)
                try:
                    archive.write(full_path, arcname=relative_path)
                except Exception as exc:
                    zip_failures += 1
                    pipboy_log_error(f"backup ZIP member {relative_path}", exc)
    return {"failures": failures + zip_failures, "archive": archive_path}



def save_project():
    try:
        if not os.path.isdir(PROJECT_SAVE_DOWNLOADS_PATH):
            run_command_silent("termux-setup-storage")

        os.makedirs(PROJECT_SAVE_DOWNLOADS_PATH, exist_ok=True)
        _delete_existing_project_save_archives()
        archive_path = os.path.join(PROJECT_SAVE_DOWNLOADS_PATH, PROJECT_SAVE_ARCHIVE_NAME)
        result = _build_project_save_archive(archive_path)
        _copy_project_archive_to_selected_folders(archive_path)
        print(_(PROJECT_SAVE_SUCCESS_MESSAGE))
        if result.get("failures"):
            print(pipboy_text(
                f"The backup was created with {result['failures']} recoverable issue(s). Read Backup Report.txt inside the ZIP.",
                f"Το αντίγραφο ασφαλείας δημιουργήθηκε με {result['failures']} ανακτήσιμο/α πρόβλημα/τα. Διαβάστε το Backup Report.txt μέσα στο ZIP.",
            ))
    except Exception as error:
        pipboy_log_error("Save DedSec Project", error)
        print(_("Failed to save project: ") + str(error))
    finally:
        _remove_path_if_exists(PROJECT_SAVE_WORKDIR)



# ----------------------------------------------------------------------
# Offline Termux Transfer System
# ----------------------------------------------------------------------
def _transfer_safe_rel(path):
    """Normalize one transfer-relative path and reject traversal/control characters."""
    raw = str(path or "").replace("\\", "/").lstrip("/")
    parts = []
    for part in raw.split("/"):
        if part in ("", "."):
            continue
        if part == ".." or any(ch in part for ch in ("\x00", "\r", "\n", "\t")):
            raise ValueError("Unsafe path in Termux Transfer inventory.")
        parts.append(part)
    return "/".join(parts)


def _transfer_private_path(root_kind, rel_path):
    """Return True for authentication, credential, secret, or volatile paths.

    The transfer intentionally prefers losing a private configuration file over
    copying a credential to another phone. Normal project source/config remains
    eligible unless its path or content is secret-like.
    """
    rel = _transfer_safe_rel(rel_path)
    low = rel.casefold()
    parts = [part.casefold() for part in rel.split("/") if part]
    base = parts[-1] if parts else ""

    # Never recursively archive the transfer's own work/output or transient state.
    if root_kind == "home":
        blocked_roots = {
            ".ssh", ".gnupg", ".aws", ".azure", ".docker", ".kube",
            ".password-store", ".termux_transfer", ".dedsec_termux_transfer_work",
        }
        if parts and parts[0] in blocked_roots:
            return True
        blocked_sequences = (
            ".config/gh/", ".config/gcloud/", ".local/share/keyrings/",
            ".mozilla/firefox/", ".pki/nssdb/",
        )
        padded = low + ("/" if low and not low.endswith("/") else "")
        if any(seq in padded for seq in blocked_sequences):
            return True
        if "/.git/config" in "/" + low or low.endswith("/.git/config"):
            return True
        if base in {
            ".git-credentials", ".netrc", ".npmrc", ".pypirc", ".bash_history",
            ".zsh_history", ".python_history", "known_hosts", "authorized_keys",
            "credentials", "credentials.json", "secrets.json", "auth.json",
        }:
            return True
        if base == ".env" or base.startswith(".env."):
            return True
        secret_words = ("token", "secret", "credential", "password", "passwd", "private_key", "private-key")
        stem = base.rsplit(".", 1)[0]
        if any(word == stem or stem.startswith(word + "_") or stem.startswith(word + "-") for word in secret_words):
            return True
        if base.endswith((".p12", ".pfx", ".kdbx")):
            return True
        # Private-key style files in user/project space. Do not apply to Prefix CA certs.
        if base.endswith((".key", ".pem")) and any(part in {"ssh", "keys", "certs", "secrets", "credentials"} for part in parts[:-1]):
            return True
        if low == os.path.basename(GITHUB_ACCOUNT_CONFIG_PATH).casefold() or low.endswith("/" + os.path.basename(GITHUB_ACCOUNT_CONFIG_PATH).casefold()):
            return True
        if low.startswith("dedsec os/runtime/"):
            return True
    else:
        if low.startswith(("tmp/", "var/run/", "var/tmp/")):
            return True
        if low.startswith("etc/apt/auth.conf") or "/auth.conf.d/" in "/" + low:
            return True
        if base.startswith("lock") and any(x in low for x in ("var/lib/dpkg/", "var/lib/apt/", "var/cache/apt/")):
            return True
    return False


def _transfer_file_contains_secret(path, root_kind):
    """Stream-scan transferable text files for common credential material.

    Earlier builds skipped content scanning entirely once a file exceeded 2 MiB.
    That created a privacy gap for large source/config/log files.  This version
    keeps memory bounded while scanning the *entire* eligible file, using a small
    overlap so credentials split across read boundaries are still detected.
    """
    if root_kind != "home":
        return False
    try:
        size = os.path.getsize(path)
    except OSError:
        return False
    if size <= 0:
        return False
    ext = os.path.splitext(path)[1].casefold()
    text_exts = {
        ".py", ".sh", ".bash", ".zsh", ".js", ".ts", ".json", ".yaml", ".yml",
        ".toml", ".ini", ".cfg", ".conf", ".txt", ".md", ".xml", ".html",
        ".css", ".properties", ".gradle", ".env", ".gitconfig", ".log", ".csv",
    }
    if ext not in text_exts and os.path.basename(path).casefold() not in {"config", "settings", "settings.json"}:
        return False
    patterns = tuple(re.compile(pattern, re.I) for pattern in (
        rb"-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----",
        rb"\bgh[pousr]_[A-Za-z0-9_]{20,}\b",
        rb"\bgithub_pat_[A-Za-z0-9_]{20,}\b",
        rb"\bAKIA[0-9A-Z]{16}\b",
        rb"\b(?:api[_-]?key|access[_-]?token|auth[_-]?token|secret|password|passwd)\b\s*[:=]\s*[\"']?[A-Za-z0-9_./+=:@-]{12,}",
        rb"authorization\s*[:=]\s*[\"']?bearer\s+[A-Za-z0-9._~+/=-]{12,}",
    ))
    chunk_size = max(256 * 1024, int(TERMUX_TRANSFER_SECRET_SCAN_MAX_BYTES or (2 * 1024 * 1024)))
    overlap_size = 8192
    try:
        with open(path, "rb") as handle:
            probe = handle.read(4096)
            if b"\x00" in probe:
                return False
            handle.seek(0)
            overlap = b""
            while True:
                block = handle.read(chunk_size)
                if not block:
                    break
                window = overlap + block
                if any(pattern.search(window) for pattern in patterns):
                    return True
                overlap = window[-overlap_size:]
    except (OSError, ValueError):
        return False
    return False


def _transfer_is_core(root_kind, rel_path, size=0):
    rel = _transfer_safe_rel(rel_path)
    low = rel.casefold()
    # Large files never belong to Core.zip; Core stays quick and mandatory.
    if int(size or 0) > 50 * 1024 * 1024:
        return False
    if root_kind == "usr":
        return low.startswith("etc/") or low.startswith("var/lib/dpkg/") or low in {"var/lib/apt/extended_states"}
    if "/" not in rel:
        return True
    return (
        low.startswith(".termux/")
        or low in {"dedsec/scripts/settings.py", "language.json", "dedsec os/config.json"}
    )


def _transfer_inventory():
    entries = []
    excluded = {"private": 0, "volatile": 0, "unsupported": 0, "secret_content": 0}
    roots = (("home", HOME_DIR), ("usr", TERMUX_TRANSFER_PREFIX))
    for root_kind, root in roots:
        if not os.path.isdir(root):
            continue
        for current, dirnames, filenames in os.walk(root, topdown=True, followlinks=False):
            rel_current = os.path.relpath(current, root)
            if rel_current == ".":
                rel_current = ""
            kept_dirs = []
            for name in list(dirnames):
                src = os.path.join(current, name)
                rel = os.path.join(rel_current, name) if rel_current else name
                if _transfer_private_path(root_kind, rel):
                    excluded["private"] += 1
                    continue
                try:
                    st = os.lstat(src)
                except OSError:
                    excluded["unsupported"] += 1
                    continue
                arc = f"payload/{root_kind}/{_transfer_safe_rel(rel)}"
                if stat.S_ISLNK(st.st_mode):
                    entries.append({"kind": "symlink", "root": root_kind, "src": src, "rel": rel, "arc": arc, "size": len(os.readlink(src).encode("utf-8", errors="replace")), "mode": stat.S_IMODE(st.st_mode), "core": _transfer_is_core(root_kind, rel, 0)})
                    continue
                if stat.S_ISDIR(st.st_mode):
                    kept_dirs.append(name)
                    entries.append({"kind": "dir", "root": root_kind, "src": src, "rel": rel, "arc": arc.rstrip("/") + "/", "size": 0, "mode": stat.S_IMODE(st.st_mode), "core": _transfer_is_core(root_kind, rel, 0)})
            dirnames[:] = kept_dirs
            for name in filenames:
                src = os.path.join(current, name)
                rel = os.path.join(rel_current, name) if rel_current else name
                if _transfer_private_path(root_kind, rel):
                    excluded["private"] += 1
                    continue
                try:
                    st = os.lstat(src)
                except OSError:
                    excluded["unsupported"] += 1
                    continue
                arc = f"payload/{root_kind}/{_transfer_safe_rel(rel)}"
                if stat.S_ISLNK(st.st_mode):
                    try:
                        target = os.readlink(src)
                    except OSError:
                        excluded["unsupported"] += 1
                        continue
                    entries.append({"kind": "symlink", "root": root_kind, "src": src, "rel": rel, "arc": arc, "size": len(target.encode("utf-8", errors="replace")), "mode": stat.S_IMODE(st.st_mode), "core": _transfer_is_core(root_kind, rel, 0)})
                elif stat.S_ISREG(st.st_mode):
                    if _transfer_file_contains_secret(src, root_kind):
                        excluded["secret_content"] += 1
                        continue
                    entries.append({"kind": "file", "root": root_kind, "src": src, "rel": rel, "arc": arc, "size": int(st.st_size), "mode": stat.S_IMODE(st.st_mode), "core": _transfer_is_core(root_kind, rel, st.st_size)})
                else:
                    excluded["unsupported"] += 1
    return entries, excluded


def _transfer_zip_add_entry(zf, entry, arcname=None):
    arcname = arcname or entry["arc"]
    if entry["kind"] == "dir":
        info = zipfile.ZipInfo(arcname.rstrip("/") + "/")
        info.create_system = 3
        info.external_attr = ((stat.S_IFDIR | int(entry.get("mode", 0o755))) << 16) | 0x10
        zf.writestr(info, b"")
    elif entry["kind"] == "symlink":
        # Do not create symlinks in the ZIP extraction staging tree. An extractor
        # could otherwise follow a parent symlink while processing a later member.
        # Install.sh recreates transfer symlinks only after regular files are copied.
        return
    else:
        zf.write(entry["src"], arcname=arcname, compress_type=zipfile.ZIP_STORED)


def _transfer_new_data_archive(index):
    name = f"Data-{index:03d}.zip"
    path = os.path.join(TERMUX_TRANSFER_DIR, name)
    return name, path, zipfile.ZipFile(path, "w", compression=zipfile.ZIP_STORED, allowZip64=True)


def _transfer_write_data_archives(entries):
    data_entries = [entry for entry in entries if not entry.get("core")]
    archive_names = []
    split_records = []
    current = None
    current_name = None
    current_size = 0
    archive_index = 0

    def ensure_archive(required=0):
        nonlocal current, current_name, current_size, archive_index
        if current is None or (current_size and current_size + int(required) + 65536 > TERMUX_TRANSFER_TARGET_BYTES):
            if current is not None:
                current.close()
            archive_index += 1
            current_name, _path, current = _transfer_new_data_archive(archive_index)
            archive_names.append(current_name)
            current_size = 0
        return current

    try:
        for entry in data_entries:
            if entry["kind"] != "file" or entry["size"] <= TERMUX_TRANSFER_TARGET_BYTES - 131072:
                zf = ensure_archive(entry.get("size", 0))
                _transfer_zip_add_entry(zf, entry)
                current_size += int(entry.get("size", 0)) + 1024
                continue

            # Oversized individual files are streamed into portable sub-parts.
            split_id = hashlib.sha256(entry["arc"].encode("utf-8", errors="replace")).hexdigest()[:20]
            part_dir = f"split/{split_id}"
            parts = []
            with open(entry["src"], "rb") as source:
                part_index = 0
                while True:
                    part_index += 1
                    temp_part = os.path.join(TERMUX_TRANSFER_WORKDIR, f"{split_id}-{part_index:04d}.part")
                    written = 0
                    with open(temp_part, "wb") as out:
                        while written < TERMUX_TRANSFER_SPLIT_PART_BYTES:
                            block = source.read(min(16 * 1024 * 1024, TERMUX_TRANSFER_SPLIT_PART_BYTES - written))
                            if not block:
                                break
                            out.write(block)
                            written += len(block)
                    if written == 0:
                        try: os.remove(temp_part)
                        except OSError: pass
                        break
                    zf = ensure_archive(written)
                    part_arc = f"{part_dir}/part-{part_index:04d}"
                    zf.write(temp_part, arcname=part_arc, compress_type=zipfile.ZIP_STORED)
                    current_size += written + 1024
                    parts.append(part_arc)
                    os.remove(temp_part)
            split_records.append({"target": entry["arc"], "mode": entry.get("mode", 0o600), "part_dir": part_dir, "parts": parts})
    finally:
        if current is not None:
            current.close()
    return archive_names, split_records


def _transfer_package_list():
    try:
        result = subprocess.run(["dpkg-query", "-W", "-f=${binary:Package}\\t${Version}\\n"], capture_output=True, text=True, timeout=60, check=False)
        if result.returncode == 0:
            return result.stdout
    except Exception:
        pass
    return ""


def _transfer_write_core(entries, split_records, excluded):
    core_path = os.path.join(TERMUX_TRANSFER_DIR, TERMUX_TRANSFER_CORE_NAME)
    metadata = {
        "schema": 1,
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "source_arch": os.uname().machine,
        "source_prefix": TERMUX_TRANSFER_PREFIX,
        "source_home": HOME_DIR,
        "android_sdk": run_command_silent("getprop ro.build.version.sdk")[0],
        "privacy": {
            "private_paths_excluded": int(excluded.get("private", 0)),
            "secret_content_excluded": int(excluded.get("secret_content", 0)),
            "volatile_or_unsupported_excluded": int(excluded.get("volatile", 0)) + int(excluded.get("unsupported", 0)),
        },
    }
    split_lines = []
    for record in split_records:
        split_lines.append(f"{record['target']}\t{int(record['mode']):o}\t{record['part_dir']}")
    with zipfile.ZipFile(core_path, "w", compression=zipfile.ZIP_STORED, allowZip64=True) as zf:
        for entry in entries:
            if entry.get("core"):
                _transfer_zip_add_entry(zf, entry)
        zf.writestr("metadata/Transfer.json", json.dumps(metadata, indent=2, ensure_ascii=False).encode("utf-8"))
        zf.writestr("metadata/Package List.txt", _transfer_package_list().encode("utf-8", errors="replace"))
        zf.writestr("metadata/Split Files.tsv", ("\n".join(split_lines) + ("\n" if split_lines else "")).encode("utf-8"))
    if os.path.getsize(core_path) > TERMUX_TRANSFER_HARD_MAX_BYTES:
        raise RuntimeError("Core.zip exceeded the 1.5 GB hard limit; transfer was aborted safely.")
    return core_path, metadata


def _transfer_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            block = handle.read(8 * 1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def _transfer_collect_unzip_runtime():
    unzip_path = shutil.which("unzip")
    if not unzip_path and shutil.which("pkg"):
        print("[+] Offline restore needs unzip. Trying to prepare it on this phone...")
        try:
            subprocess.run(["pkg", "install", "-y", "unzip"], timeout=240, check=False)
        except Exception:
            pass
        unzip_path = shutil.which("unzip")
    if not unzip_path or not os.path.isfile(unzip_path):
        return []
    files = [("bin/unzip", unzip_path)]
    try:
        result = subprocess.run(["ldd", unzip_path], capture_output=True, text=True, timeout=20, check=False)
        seen = set()
        for candidate in re.findall(r"(/[^\s()]+\.so(?:\.[0-9]+)*)", (result.stdout or "") + "\n" + (result.stderr or "")):
            if candidate.startswith(TERMUX_TRANSFER_PREFIX + os.sep) and os.path.isfile(candidate):
                name = os.path.basename(candidate)
                if name not in seen:
                    seen.add(name)
                    files.append(("lib/" + name, candidate))
    except Exception:
        pass
    return files


def _transfer_b64_shell_block(label, path):
    data = base64.b64encode(open(path, "rb").read()).decode("ascii")
    wrapped = "\n".join(textwrap.wrap(data, 76))
    quoted = shlex.quote(label)
    return f"""mkdir -p "$BOOT/$(dirname {quoted})"\ncat > "$BOOT/{label}.b64" <<'DEDSEC_TRANSFER_B64'\n{wrapped}\nDEDSEC_TRANSFER_B64\nbase64 -d "$BOOT/{label}.b64" > "$BOOT/{label}"\nrm -f "$BOOT/{label}.b64"\n"""


def _transfer_install_script(archives, metadata, entries):
    bootstrap_files = _transfer_collect_unzip_runtime()
    bootstrap = "".join(_transfer_b64_shell_block(label, path) for label, path in bootstrap_files)
    if any(label == "bin/unzip" for label, _path in bootstrap_files):
        bootstrap += 'chmod 700 "$BOOT/bin/unzip"\n'
    checks = []
    for name in archives:
        path = os.path.join(TERMUX_TRANSFER_DIR, name)
        checks.append((_transfer_sha256(path), name, os.path.getsize(path)))
    verify_lines = "\n".join(
        f"verify_archive {shlex.quote(digest)} {shlex.quote(name)} {size}"
        for digest, name, size in checks
    )
    source_arch = shlex.quote(str(metadata.get("source_arch") or ""))
    source_prefix = shlex.quote(str(metadata.get("source_prefix") or TERMUX_TRANSFER_PREFIX))
    source_sdk = shlex.quote(str(metadata.get("android_sdk") or ""))
    symlink_restore_lines = []
    for entry in entries:
        if entry.get("kind") != "symlink":
            continue
        root_kind = str(entry.get("root") or "")
        if root_kind not in {"home", "usr"}:
            continue
        rel = _transfer_safe_rel(entry.get("rel") or "")
        if not rel:
            continue
        try:
            target = os.readlink(entry["src"])
        except OSError:
            continue
        symlink_restore_lines.append(
            "restore_symlink " + shlex.quote(root_kind) + " " + shlex.quote(rel) + " " + shlex.quote(target)
        )
    symlink_restore_block = "\n".join(symlink_restore_lines)
    script = f"""#!/data/data/com.termux/files/usr/bin/bash
set -eu
umask 077

TRANSFER_DIR="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
STAGE="$HOME/.termux_transfer_restore"
BOOT="$STAGE/bootstrap"
PRE="$HOME/.termux_transfer_pre_restore"
SOURCE_ARCH={source_arch}
SOURCE_PREFIX={source_prefix}
SOURCE_SDK={source_sdk}

fail() {{ echo "[!] $*" >&2; exit 1; }}
[ "$(uname -m)" = "$SOURCE_ARCH" ] || fail "CPU architecture mismatch: transfer=$SOURCE_ARCH, device=$(uname -m)."
[ "${{PREFIX:-/data/data/com.termux/files/usr}}" = "$SOURCE_PREFIX" ] || fail "Termux prefix mismatch. Expected $SOURCE_PREFIX."
CURRENT_SDK="$(getprop ro.build.version.sdk 2>/dev/null || true)"
if [ -n "$SOURCE_SDK" ] && [ -n "$CURRENT_SDK" ] && [ "$SOURCE_SDK" != "$CURRENT_SDK" ]; then
  echo "[!] Android SDK differs (old $SOURCE_SDK, new $CURRENT_SDK). Portable data will restore, but native packages may need repair later."
fi

cd "$TRANSFER_DIR"
[ -f "{TERMUX_TRANSFER_CORE_NAME}" ] || fail "{TERMUX_TRANSFER_CORE_NAME} is missing. Transfer it from the old phone."
rm -rf "$STAGE"
mkdir -p "$BOOT"

verify_archive() {{
  expected="$1"; file="$2"; expected_size="$3"
  [ -f "$file" ] || fail "Missing transfer archive: $file"
  actual_size="$(wc -c < "$file" | tr -d ' ')"
  [ "$actual_size" = "$expected_size" ] || fail "Size check failed for $file"
  actual="$(sha256sum "$file" | awk '{{print $1}}')"
  [ "$actual" = "$expected" ] || fail "SHA-256 check failed for $file"
}}

{verify_lines}
echo "[+] All transfer archives passed integrity checks."

# Offline unzip bootstrap captured from the old Termux installation.
{bootstrap}
extract_zip() {{
  file="$1"
  if command -v unzip >/dev/null 2>&1; then
    unzip -oq "$file" -d "$STAGE"
    return
  fi
  if [ -x "$BOOT/bin/unzip" ]; then
    LD_LIBRARY_PATH="$BOOT/lib:${{PREFIX:-/data/data/com.termux/files/usr}}/lib" "$BOOT/bin/unzip" -oq "$file" -d "$STAGE"
    return
  fi
  if command -v python3 >/dev/null 2>&1; then
    python3 -m zipfile -e "$file" "$STAGE"
    return
  fi
  if command -v pkg >/dev/null 2>&1; then
    echo "[!] Offline unzip bootstrap is unavailable. Internet fallback will be attempted only now."
    pkg install -y unzip >/dev/null 2>&1 || fail "No offline unzip runtime and internet installation failed."
    unzip -oq "$file" -d "$STAGE"
    return
  fi
  fail "No ZIP extractor is available."
}}

extract_zip "{TERMUX_TRANSFER_CORE_NAME}"\n"""
    for name in archives:
        if name != TERMUX_TRANSFER_CORE_NAME:
            script += f'extract_zip {shlex.quote(name)}\n'
    script += r"""

# Reassemble files that were larger than a safe archive payload.
SPLIT_MANIFEST="$STAGE/metadata/Split Files.tsv"
if [ -f "$SPLIT_MANIFEST" ]; then
  TAB="$(printf '\t')"
  while IFS="$TAB" read -r target mode part_dir; do
    [ -n "$target" ] || continue
    mkdir -p "$(dirname "$STAGE/$target")"
    : > "$STAGE/$target"
    found=0
    for part in "$STAGE/$part_dir"/part-*; do
      [ -f "$part" ] || continue
      cat "$part" >> "$STAGE/$target"
      found=1
    done
    [ "$found" = 1 ] || fail "Missing split parts for $target"
    chmod "$mode" "$STAGE/$target" 2>/dev/null || true
  done < "$SPLIT_MANIFEST"
fi

# Preserve a small clean-install rollback point before overlaying the transfer.
rm -rf "$PRE"
mkdir -p "$PRE"
[ -d "$PREFIX/etc" ] && cp -a "$PREFIX/etc" "$PRE/usr-etc" 2>/dev/null || true
[ -d "$HOME/.termux" ] && cp -a "$HOME/.termux" "$PRE/home-termux" 2>/dev/null || true
[ -f "$HOME/.bashrc" ] && cp -a "$HOME/.bashrc" "$PRE/home-bashrc" 2>/dev/null || true

# Overlay Prefix first, then HOME. Credentials/private material was excluded on source.
if [ -d "$STAGE/payload/usr" ]; then
  cp -a "$STAGE/payload/usr/." "$PREFIX/"
fi
if [ -d "$STAGE/payload/home" ]; then
  cp -a "$STAGE/payload/home/." "$HOME/"
fi

# Recreate symlinks only now, after archive extraction and regular-file overlay.
restore_symlink() {
  root_kind="$1"; rel="$2"; target="$3"
  case "$rel" in ''|/*|..|../*|*/..|*/../*) fail "Unsafe symlink path in transfer: $rel" ;; esac
  case "$root_kind" in home) base="$HOME" ;; usr) base="$PREFIX" ;; *) fail "Unknown symlink root: $root_kind" ;; esac
  link="$base/$rel"
  mkdir -p "$(dirname "$link")"
  if [ -L "$link" ] || [ -f "$link" ]; then
    rm -f -- "$link"
  elif [ -e "$link" ]; then
    echo "[!] Existing directory prevented symlink restore: $link"
    return 0
  fi
  ln -s -- "$target" "$link"
}
__DEDSEC_SYMLINK_RESTORE__

rm -f "$PREFIX/var/lib/dpkg/lock" "$PREFIX/var/lib/dpkg/lock-frontend" "$PREFIX/var/lib/apt/lists/lock" 2>/dev/null || true
hash -r 2>/dev/null || true
command -v termux-reload-settings >/dev/null 2>&1 && termux-reload-settings >/dev/null 2>&1 || true
rm -rf "$STAGE"
echo "[+] Termux Transfer restore completed."
echo "[+] Close Termux completely and open it again."
echo "[+] Private credentials/tokens/SSH/GitHub authentication were intentionally NOT transferred."
"""
    script = script.replace("__DEDSEC_SYMLINK_RESTORE__", symlink_restore_block)
    return script


