def sanitize_prompt_username(username):
    """Keeps the Termux prompt safe while preserving normal GitHub usernames."""
    username = (username or "").strip()
    username = re.sub(r"[^A-Za-z0-9_.@-]", "_", username)
    return username[:48] or "DedSec"


def build_dedsec_ps1(username):
    username = sanitize_prompt_username(username)
    return (
        f"PS1='\\[\\e[1;36m\\]\\D{{%d/%m/%Y}}-[\\A]-(\\[\\e[1;34m\\]{username}\\[\\e[0m\\])-(\\[\\e[1;33m\\]\\W\\[\\e[0m\\]) : '\n"
    )


def atomic_write_bashrc(content):
    """Atomically replace bash.bashrc while preserving its current mode.

    All DedSec writers use a unique temporary file plus fsync/os.replace so an
    interrupted customization cannot leave Termux with a truncated startup file.
    A small advisory lock serializes concurrent DedSec writers.
    """
    directory = os.path.dirname(BASHRC_PATH) or "."
    os.makedirs(directory, exist_ok=True)
    lock_path = BASHRC_PATH + ".dedsec.lock"
    lock_fd = os.open(lock_path, os.O_CREAT | os.O_RDWR, 0o600)
    temp_path = BASHRC_PATH + f".tmp-{os.getpid()}-{uuid.uuid4().hex}"
    try:
        fcntl.flock(lock_fd, fcntl.LOCK_EX)
        try:
            mode = stat.S_IMODE(os.stat(BASHRC_PATH).st_mode)
        except OSError:
            mode = 0o600
        with open(temp_path, "w", encoding="utf-8", newline="") as handle:
            handle.write(str(content))
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_path, mode)
        os.replace(temp_path, BASHRC_PATH)
        try:
            dir_fd = os.open(directory, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except OSError:
            pass
        return True
    finally:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass
        try:
            fcntl.flock(lock_fd, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(lock_fd)


def set_prompt_username(username):
    """Updates bash.bashrc PS1 without asking for input."""
    username = sanitize_prompt_username(username)
    remove_motd()
    try:
        os.makedirs(os.path.dirname(BASHRC_PATH), exist_ok=True)
        if os.path.exists(BASHRC_PATH):
            with open(BASHRC_PATH, "r") as bashrc_file:
                lines = bashrc_file.readlines()
        else:
            lines = []

        new_ps1 = build_dedsec_ps1(username)
        output = []
        ps1_replaced = False
        for line in lines:
            if line.strip().startswith("PS1="):
                output.append(new_ps1)
                ps1_replaced = True
            else:
                output.append(line)
        if not ps1_replaced:
            output.append(new_ps1)
        return atomic_write_bashrc("".join(output))
    except Exception as error:
        print(f"[!] Failed to update prompt: {error}")
        return False


def modify_bashrc():
    username = input(f"{_('Prompt Username')}: ").strip()
    while not username:
        print(_("Username cannot be empty. Please enter a valid username."))
        username = input(f"{_('Prompt Username')}: ").strip()
    set_prompt_username(username)


def change_prompt():
    print(f"\n[+] {_('Changing Prompt...')} \n")
    modify_bashrc()
    print(f"\n[+] {_('Customizations applied successfully! ')}")

