# Update Packages & Modules
# ------------------------------
def update_packages_modules():
    """Update DedSec dependencies through the canonical Setup.sh installer."""
    root = find_dedsec()
    setup_path = os.path.join(root, "Setup.sh") if root else ""

    if not setup_path or not os.path.isfile(setup_path):
        print(pipboy_text(
            "[!] Setup.sh was not found. Dependency update was not started.",
            "[!] Δεν βρέθηκε το Setup.sh. Η ενημέρωση εξαρτήσεων δεν ξεκίνησε.",
        ))
        return

    print(pipboy_text(
        "[+] Updating packages and modules through Setup.sh...",
        "[+] Ενημέρωση πακέτων και modules μέσω του Setup.sh...",
    ))

    result = subprocess.run(
        ["bash", setup_path, "--update-only"],
        cwd=root,
        check=False,
    )

    if result.returncode != 0:
        print(pipboy_text(
            f"[!] Setup.sh dependency update failed with exit code {result.returncode}.",
            f"[!] Η ενημέρωση εξαρτήσεων μέσω Setup.sh απέτυχε με κωδικό {result.returncode}.",
        ))
        return

    print(pipboy_text(
        "[+] Packages and modules were updated successfully through Setup.sh.",
        "[+] Τα πακέτα και τα modules ενημερώθηκαν επιτυχώς μέσω του Setup.sh.",
    ))

    try:
        pipboy_refresh_knowledge_after_update(
            trigger="packages_modules_update", force_project_rebuild=False, quiet=False
        )
    except Exception as exc:
        try:
            pipboy_log_error("packages update knowledge refresh", exc)
        except Exception:
            pass
        print(pipboy_text(
            f"[!] Packages were updated, but the Ded-Guy database check failed: {exc}",
            f"[!] Τα πακέτα ενημερώθηκαν, αλλά ο έλεγχος βάσης Ded-Guy απέτυχε: {exc}",
        ))

# ------------------------------
# --- Backup and Uninstall ---
# ------------------------------

def create_backup_zip_if_not_exists():
    """Creates a zip backup of original config files on first run."""
    if os.path.exists(BACKUP_ZIP_PATH):
        return 
    
    print(_("Creating one-time configuration backup to Termux.zip..."))
    try:
        with zipfile.ZipFile(BACKUP_ZIP_PATH, 'w', zipfile.ZIP_DEFLATED) as zf:
            if os.path.exists(BASHRC_PATH):
                zf.write(BASHRC_PATH, arcname=BASHRC_PATH)
            if os.path.exists(MOTD_PATH):
                zf.write(MOTD_PATH, arcname=MOTD_PATH)
        print(_("Backup successful."))
    except Exception as e:
        print(f"{_('Warning: Failed to create backup: ')}{e}")

def restore_configuration_backup(backup_path=BACKUP_ZIP_PATH):
    """Restore only the two configuration files created by our own backup routine.

    Never extract an arbitrary ZIP to ``/``: the backup file lives in HOME and can
    be replaced or corrupted independently of Settings.py.
    """
    targets = {
        os.path.basename(BASHRC_PATH): BASHRC_PATH,
        os.path.basename(MOTD_PATH): MOTD_PATH,
    }
    restored = []
    with zipfile.ZipFile(backup_path, "r") as archive:
        infos = archive.infolist()
        if len(infos) > 16:
            raise ValueError("Configuration backup contains unexpected extra entries.")
        for basename, destination in targets.items():
            candidates = []
            for info in infos:
                normalized = str(info.filename or "").replace("\\", "/").rstrip("/")
                if normalized and normalized.split("/")[-1] == basename and not info.is_dir():
                    candidates.append(info)
            if not candidates:
                continue
            if len(candidates) != 1:
                raise ValueError("Configuration backup contains duplicate " + basename + " entries.")
            info = candidates[0]
            if int(info.file_size or 0) > 16 * 1024 * 1024:
                raise ValueError("Configuration backup entry is unexpectedly large: " + basename)
            data = archive.read(info)
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            temp = destination + ".dedsec-restore.tmp"
            with open(temp, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            try:
                current_mode = stat.S_IMODE(os.stat(destination).st_mode) if os.path.exists(destination) else 0o600
                os.chmod(temp, current_mode)
            except OSError:
                pass
            os.replace(temp, destination)
            restored.append(destination)
    return restored


def uninstall_dedsec():
    """Restores config files from backup and instructs user on final folder removal."""
    print(f"--- {_('Uninstall DedSec Project')} ---")
    confirm = input(_("This will restore backed-up files and remove the DedSec project. ARE YOU SURE? (y/n): ")).lower().strip()
    
    if confirm != 'y':
        print(_("Uninstallation cancelled."))
        return False

    if os.path.exists(BACKUP_ZIP_PATH):
        print(_("Restoring files from Termux.zip..."))
        try:
            restored = restore_configuration_backup(BACKUP_ZIP_PATH)
            if not restored:
                raise ValueError("Termux.zip did not contain the expected configuration files.")
            print(_("Restored bash.bashrc and motd from backup."))
            os.remove(BACKUP_ZIP_PATH)
            print(_("Removed Termux.zip backup."))
        except Exception as e:
            print(f"{_('Error restoring from backup: ')}{e}")
    else:
        print(_("Backup Termux.zip not found. Cleaning up configuration manually..."))
        cleanup_bashrc()

    if os.path.exists(LANGUAGE_JSON_PATH):
        print(_("Removing language configuration..."))
        os.remove(LANGUAGE_JSON_PATH)

    dedsec_path = find_dedsec()
    if not dedsec_path:
        dedsec_path = os.path.join(HOME_DIR, LOCAL_DIR) 

    print("\n" + "="*40)
    print(" [!] UNINSTALLATION ALMOST COMPLETE [!]")
    print("="*40)
    print(_("Configuration files have been reset."))
    print(_("To complete the uninstallation, please exit this script and run the following command:"))
    print(f"\n    rm -rf \"{dedsec_path}\"\n")
    print(_("Exiting..."))
    
    return True

