def q(ns,tag): return '{%s}%s'%(ns,tag)

def zip_replace(template_bytes, replacements, removals=(), additions=None, stored_first_mimetype=False):
    src=zipfile.ZipFile(io.BytesIO(template_bytes),'r')
    out=io.BytesIO()
    with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as dst:
        if stored_first_mimetype and 'mimetype' in src.namelist():
            zi=zipfile.ZipInfo('mimetype'); zi.compress_type=zipfile.ZIP_STORED
            dst.writestr(zi, src.read('mimetype'))
        for info in src.infolist():
            name=info.filename
            if stored_first_mimetype and name=='mimetype': continue
            if name in removals or any(name.startswith(prefix) for prefix in removals if prefix.endswith('/')): continue
            data=replacements.get(name,src.read(name))
            dst.writestr(info,data)
        for name,data in (additions or {}).items():
            if name in replacements: continue
            dst.writestr(name,data)
    src.close(); return out.getvalue()

class OfficeHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.paragraphs=[]; self.runs=[]; self.style='p'; self.align='left'
        self.bold=0; self.italic=0; self.underline=0; self.strike=0
        self.color_stack=[]; self.face_stack=[]; self.size_stack=[]
        self.color=''; self.face=''; self.size=''
    @staticmethod
    def _attrs(attrs):
        return {str(k or '').lower(): str(v or '') for k,v in attrs}
    @staticmethod
    def _css(attrs):
        raw=OfficeHTMLParser._attrs(attrs).get('style','')
        out={}
        for part in raw.split(';'):
            if ':' in part:
                k,v=part.split(':',1); out[k.strip().lower()]=v.strip()
        return out
    @staticmethod
    def _hex_color(value):
        value=str(value or '').strip()
        m=re.fullmatch(r'#?([0-9a-fA-F]{6})',value)
        return m.group(1).upper() if m else ''
    def _run(self,text):
        return {'text':text,'bold':bool(self.bold),'italic':bool(self.italic),'underline':bool(self.underline),'strike':bool(self.strike),'color':self.color,'face':self.face,'size':self.size}
    def flush(self,force=False):
        if self.runs or force:
            self.paragraphs.append({'style':self.style,'align':self.align,'runs':self.runs[:]})
            self.runs=[]; self.style='p'; self.align='left'
    def handle_starttag(self,tag,attrs):
        tag=tag.lower(); amap=self._attrs(attrs); css=self._css(attrs)
        if tag in ('p','div','h1','h2','h3','h4','h5','h6','li'):
            if self.runs:self.flush()
            self.style=tag
            align=(amap.get('align') or css.get('text-align') or 'left').lower()
            self.align=align if align in {'left','center','right','justify'} else 'left'
            if tag=='li': self.runs.append(self._run('• '))
        elif tag in ('b','strong'): self.bold+=1
        elif tag in ('i','em'): self.italic+=1
        elif tag=='u': self.underline+=1
        elif tag in ('s','strike','del'): self.strike+=1
        elif tag=='font':
            self.color_stack.append(self.color); self.face_stack.append(self.face); self.size_stack.append(self.size)
            self.color=self._hex_color(amap.get('color')) or self.color
            self.face=(amap.get('face') or self.face)[:80]
            self.size=(amap.get('size') or self.size)[:8]
        elif tag=='span':
            self.color_stack.append(self.color); self.face_stack.append(self.face); self.size_stack.append(self.size)
            self.color=self._hex_color(css.get('color')) or self.color
            self.face=(css.get('font-family','').split(',')[0].strip(' \"\'') or self.face)[:80]
            fs=css.get('font-size','').lower().replace('pt','').strip()
            if fs and re.fullmatch(r'\d+(?:\.\d+)?',fs): self.size=fs
        elif tag=='br': self.runs.append(self._run('\n'))
    def handle_endtag(self,tag):
        tag=tag.lower()
        if tag in ('p','div','h1','h2','h3','h4','h5','h6','li'): self.flush(True)
        elif tag in ('b','strong'): self.bold=max(0,self.bold-1)
        elif tag in ('i','em'): self.italic=max(0,self.italic-1)
        elif tag=='u': self.underline=max(0,self.underline-1)
        elif tag in ('s','strike','del'): self.strike=max(0,self.strike-1)
        elif tag in ('font','span'):
            if self.color_stack:self.color=self.color_stack.pop()
            if self.face_stack:self.face=self.face_stack.pop()
            if self.size_stack:self.size=self.size_stack.pop()
    def handle_data(self,data):
        if data:self.runs.append(self._run(data))
    def finish(self):
        if self.runs:self.flush()
        return self.paragraphs or [{'style':'p','align':'left','runs':[self._run('')]}]

def html_paragraphs(html_text):
    p=OfficeHTMLParser(); p.feed(str(html_text or '')); return p.finish()

def html_plain_text(html_text):
    pars=html_paragraphs(html_text)
    return '\n'.join(''.join(r['text'] for r in p['runs']) for p in pars)

def docx_to_html(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        root=ET.fromstring(z.read('word/document.xml'))
    out=[]
    for pnode in root.findall('.//'+q(W,'body')+'/'+q(W,'p')):
        style='p'; pstyle=pnode.find('./'+q(W,'pPr')+'/'+q(W,'pStyle'))
        ppr=pnode.find('./'+q(W,'pPr')); align='left'
        if pstyle is not None:
            val=pstyle.attrib.get(q(W,'val'),'')
            m=re.search(r'Heading\s*([1-6])',val,re.I)
            if m: style='h'+m.group(1)
        if ppr is not None:
            jc=ppr.find(q(W,'jc'))
            if jc is not None:
                av=(jc.attrib.get(q(W,'val')) or '').lower()
                if av in {'left','center','right','both','justify'}: align='justify' if av in {'both','justify'} else av
        runs=[]
        for rnode in pnode.findall('./'+q(W,'r')):
            txt=''.join(t.text or '' for t in rnode.findall('.//'+q(W,'t')))
            if not txt and rnode.find('./'+q(W,'br')) is not None: txt='\n'
            if not txt: continue
            safe=html.escape(txt); rpr=rnode.find('./'+q(W,'rPr'))
            if rpr is not None:
                color=rpr.find(q(W,'color')); fonts=rpr.find(q(W,'rFonts')); size=rpr.find(q(W,'sz'))
                styles=[]
                if color is not None:
                    cv=color.attrib.get(q(W,'val'),'')
                    if re.fullmatch(r'[0-9A-Fa-f]{6}',cv): styles.append('color:#'+cv)
                if fonts is not None:
                    face=fonts.attrib.get(q(W,'ascii')) or fonts.attrib.get(q(W,'hAnsi')) or ''
                    if face: styles.append('font-family:'+html.escape(face,quote=True))
                if size is not None:
                    try: styles.append('font-size:'+str(float(size.attrib.get(q(W,'val'),'24'))/2)+'pt')
                    except Exception: pass
                if styles: safe='<span style="'+';'.join(styles)+'">'+safe+'</span>'
                if rpr.find(q(W,'strike')) is not None: safe='<s>'+safe+'</s>'
                if rpr.find(q(W,'u')) is not None: safe='<u>'+safe+'</u>'
                if rpr.find(q(W,'i')) is not None: safe='<i>'+safe+'</i>'
                if rpr.find(q(W,'b')) is not None: safe='<b>'+safe+'</b>'
            runs.append(safe)
        if runs:
            attr='' if align=='left' else ' style="text-align:'+align+'"'
            out.append('<%s%s>%s</%s>'%(style,attr,''.join(runs),style))
    return ''.join(out) or '<p></p>'

def docx_from_html(html_text):
    tpl=TPL['docx']; src=zipfile.ZipFile(io.BytesIO(tpl),'r'); root=ET.fromstring(src.read('word/document.xml')); src.close()
    body=root.find('.//'+q(W,'body')); sect=body.find(q(W,'sectPr'))
    for child in list(body): body.remove(child)
    size_map={'1':8,'2':10,'3':12,'4':14,'5':18,'6':24,'7':36}
    for par in html_paragraphs(html_text):
        p=ET.Element(q(W,'p')); ppr=None
        if par['style'].startswith('h'):
            ppr=ET.SubElement(p,q(W,'pPr')); ps=ET.SubElement(ppr,q(W,'pStyle')); ps.set(q(W,'val'),'Heading'+par['style'][1:])
        align=str(par.get('align') or 'left').lower()
        if align in {'center','right','justify'}:
            if ppr is None:ppr=ET.SubElement(p,q(W,'pPr'))
            jc=ET.SubElement(ppr,q(W,'jc')); jc.set(q(W,'val'),'both' if align=='justify' else align)
        for run in par['runs']:
            r=ET.SubElement(p,q(W,'r')); has_rpr=any([run.get('bold'),run.get('italic'),run.get('underline'),run.get('strike'),run.get('color'),run.get('face'),run.get('size')])
            rp=ET.SubElement(r,q(W,'rPr')) if has_rpr else None
            if rp is not None:
                if run.get('bold'): ET.SubElement(rp,q(W,'b'))
                if run.get('italic'): ET.SubElement(rp,q(W,'i'))
                if run.get('underline'):
                    u=ET.SubElement(rp,q(W,'u')); u.set(q(W,'val'),'single')
                if run.get('strike'): ET.SubElement(rp,q(W,'strike'))
                color=str(run.get('color') or '').replace('#','')
                if re.fullmatch(r'[0-9A-Fa-f]{6}',color):
                    c=ET.SubElement(rp,q(W,'color')); c.set(q(W,'val'),color.upper())
                face=str(run.get('face') or '')[:80]
                if face:
                    f=ET.SubElement(rp,q(W,'rFonts')); f.set(q(W,'ascii'),face); f.set(q(W,'hAnsi'),face)
                size=str(run.get('size') or '')
                pt=size_map.get(size)
                if pt is None:
                    try: pt=max(6,min(96,float(size))) if size else None
                    except Exception: pt=None
                if pt:
                    sz=ET.SubElement(rp,q(W,'sz')); sz.set(q(W,'val'),str(int(round(float(pt)*2))))
                    szcs=ET.SubElement(rp,q(W,'szCs')); szcs.set(q(W,'val'),str(int(round(float(pt)*2))))
            parts=str(run.get('text','')).split('\n')
            for idx,part in enumerate(parts):
                if idx: ET.SubElement(r,q(W,'br'))
                t=ET.SubElement(r,q(W,'t')); t.set('{http://www.w3.org/XML/1998/namespace}space','preserve'); t.text=part
        body.append(p)
    if sect is not None: body.append(sect)
    xml=ET.tostring(root,encoding='utf-8',xml_declaration=True)
    return zip_replace(tpl,{'word/document.xml':xml})

def _xlsx_shared(z):
    if 'xl/sharedStrings.xml' not in z.namelist(): return []
    root=ET.fromstring(z.read('xl/sharedStrings.xml')); out=[]
    for si in root.findall(q(X,'si')): out.append(''.join(t.text or '' for t in si.iter(q(X,'t'))))
    return out

def xlsx_to_cells(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        shared=_xlsx_shared(z)
        wb=ET.fromstring(z.read('xl/workbook.xml')); relroot=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        relmap={r.attrib.get('Id'):r.attrib.get('Target') for r in relroot}
        sheet=wb.find('.//'+q(X,'sheet')); rid=sheet.attrib.get(q(R,'id')); target=relmap.get(rid,'worksheets/sheet1.xml')
        path=target.lstrip('/') if target.startswith('/xl/') else ('xl/'+target.lstrip('/') if not target.startswith('xl/') else target)
        root=ET.fromstring(z.read(path))
        cells={}; maxr=40; maxc=12
        for c in root.findall('.//'+q(X,'c')):
            ref=c.attrib.get('r','A1'); t=c.attrib.get('t',''); f=c.find(q(X,'f')); v=c.find(q(X,'v'))
            if f is not None and f.text is not None: val='='+f.text
            elif t=='inlineStr': val=''.join(n.text or '' for n in c.findall('.//'+q(X,'t')))
            elif v is None: val=''
            elif t=='s':
                try: val=shared[int(v.text or '0')]
                except (ValueError, TypeError, IndexError): val=''
            elif t=='b': val='TRUE' if (v.text or '')=='1' else 'FALSE'
            else: val=v.text or ''
            if val!='': cells[ref]=val
            m=re.match(r'([A-Z]+)(\d+)',ref)
            if m:
                col=0
                for ch in m.group(1): col=col*26+ord(ch)-64
                maxc=max(maxc,col); maxr=max(maxr,int(m.group(2)))
        return {'cells':cells,'rows':min(maxr,500),'cols':min(maxc,100),'sheet_name':sheet.attrib.get('name','Sheet1')}

def xlsx_from_cells(cells,rows=40,cols=12):
    tpl=TPL['xlsx']; src=zipfile.ZipFile(io.BytesIO(tpl),'r'); root=ET.fromstring(src.read('xl/worksheets/sheet1.xml')); src.close()
    data=root.find(q(X,'sheetData'))
    for child in list(data): data.remove(child)
    def ref_parts(ref):
        m=re.match(r'^([A-Z]+)(\d+)$',ref.upper());
        if not m:return (10**9,10**9)
        col=0
        for ch in m.group(1): col=col*26+ord(ch)-64
        return int(m.group(2)),col
    grouped={}
    for ref,val in (cells or {}).items():
        if str(val)=='':continue
        r,c=ref_parts(ref)
        if r>=10**9:continue
        grouped.setdefault(r,[]).append((c,ref.upper(),str(val)))
    for rnum in sorted(grouped):
        row=ET.SubElement(data,q(X,'row')); row.set('r',str(rnum))
        for _,ref,val in sorted(grouped[rnum]):
            c=ET.SubElement(row,q(X,'c')); c.set('r',ref)
            if val.startswith('='):
                f=ET.SubElement(c,q(X,'f')); f.text=val[1:]
                v=ET.SubElement(c,q(X,'v')); v.text='0'
            else:
                try:
                    float(val); numeric=not val.strip().startswith('0') or val.strip() in ('0','0.0')
                except (ValueError, TypeError): numeric=False
                if numeric:
                    v=ET.SubElement(c,q(X,'v')); v.text=val
                else:
                    c.set('t','inlineStr'); isel=ET.SubElement(c,q(X,'is')); t=ET.SubElement(isel,q(X,'t')); t.text=val
    dim=root.find(q(X,'dimension'))
    if dim is not None:
        used_refs=[ref for group in grouped.values() for _c,ref,_v in group]
        if used_refs:
            max_row=max(ref_parts(ref)[0] for ref in used_refs)
            max_col=max(ref_parts(ref)[1] for ref in used_refs)
            dim.set('ref','A1:'+_cell_ref(max_col-1,max_row-1))
        else:
            dim.set('ref','A1')
    xml=ET.tostring(root,encoding='utf-8',xml_declaration=True)
    return zip_replace(tpl,{'xl/worksheets/sheet1.xml':xml})

def pptx_to_slides(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        names=[n for n in z.namelist() if re.fullmatch(r'ppt/slides/slide\d+\.xml',n)]
        names.sort(key=lambda n:int(re.search(r'(\d+)',n).group(1)))
        slides=[]
        for name in names:
            root=ET.fromstring(z.read(name)); texts=[n.text or '' for n in root.iter(q(A,'t'))]
            slides.append({'title':texts[0] if texts else '', 'body':'\n'.join(texts[1:])})
        return slides or [{'title':'','body':''}]

def pptx_from_slides(slides):
    slides=list(slides or [{'title':'','body':''}])[:100]
    tpl=TPL['pptx']; src=zipfile.ZipFile(io.BytesIO(tpl),'r')
    pres=ET.fromstring(src.read('ppt/presentation.xml')); rels=ET.fromstring(src.read('ppt/_rels/presentation.xml.rels')); cts=ET.fromstring(src.read('[Content_Types].xml')); slide_tpl=src.read('ppt/slides/slide1.xml'); slide_rel=src.read('ppt/slides/_rels/slide1.xml.rels'); src.close()
    sldlist=pres.find(q(P,'sldIdLst'))
    for ch in list(sldlist): sldlist.remove(ch)
    slide_type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide'
    for ch in list(rels):
        if ch.attrib.get('Type')==slide_type: rels.remove(ch)
    for ch in list(cts):
        if ch.tag==q(CT,'Override') and ch.attrib.get('PartName','').startswith('/ppt/slides/slide'): cts.remove(ch)
    additions={}
    for idx,slide in enumerate(slides,1):
        rid='rId'+str(100+idx)
        sid=ET.SubElement(sldlist,q(P,'sldId')); sid.set('id',str(255+idx)); sid.set(q(R,'id'),rid)
        rel=ET.SubElement(rels,q(PKG_REL,'Relationship')); rel.set('Id',rid); rel.set('Type',slide_type); rel.set('Target','slides/slide%d.xml'%idx)
        ov=ET.SubElement(cts,q(CT,'Override')); ov.set('PartName','/ppt/slides/slide%d.xml'%idx); ov.set('ContentType','application/vnd.openxmlformats-officedocument.presentationml.slide+xml')
        root=ET.fromstring(slide_tpl); texts=list(root.iter(q(A,'t')))
        if texts: texts[0].text=str(slide.get('title',''))
        if len(texts)>1: texts[1].text=str(slide.get('body',''))
        for extra in texts[2:]: extra.text=''
        additions['ppt/slides/slide%d.xml'%idx]=ET.tostring(root,encoding='utf-8',xml_declaration=True)
        additions['ppt/slides/_rels/slide%d.xml.rels'%idx]=slide_rel
    repl={'ppt/presentation.xml':ET.tostring(pres,encoding='utf-8',xml_declaration=True),'ppt/_rels/presentation.xml.rels':ET.tostring(rels,encoding='utf-8',xml_declaration=True),'[Content_Types].xml':ET.tostring(cts,encoding='utf-8',xml_declaration=True)}
    return zip_replace(tpl,repl,removals=('ppt/slides/',),additions=additions)

def odt_to_html(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z: root=ET.fromstring(z.read('content.xml'))
    out=[]
    for n in root.findall('.//'+q(OD_OFFICE,'text')+'/*'):
        if n.tag in (q(OD_TEXT,'p'),q(OD_TEXT,'h')):
            txt=''.join(n.itertext()); tag='h1' if n.tag==q(OD_TEXT,'h') else 'p'; out.append('<%s>%s</%s>'%(tag,html.escape(txt),tag))
    return ''.join(out) or '<p></p>'

def odt_from_html(html_text):
    tpl=TPL['odt']; src=zipfile.ZipFile(io.BytesIO(tpl),'r'); root=ET.fromstring(src.read('content.xml')); src.close(); host=root.find('.//'+q(OD_OFFICE,'text'))
    for ch in list(host): host.remove(ch)
    for par in html_paragraphs(html_text):
        tag=q(OD_TEXT,'h') if par['style'].startswith('h') else q(OD_TEXT,'p'); el=ET.SubElement(host,tag)
        if par['style'].startswith('h'): el.set(q(OD_TEXT,'outline-level'),par['style'][1:])
        el.text=''.join(r['text'] for r in par['runs'])
    return zip_replace(tpl,{'content.xml':ET.tostring(root,encoding='utf-8',xml_declaration=True)},stored_first_mimetype=True)

def ods_to_cells(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z: root=ET.fromstring(z.read('content.xml'))
    table_node=root.find('.//'+q(OD_TABLE,'table')); cells={}; maxr=40; maxc=12
    if table_node is None:return {'cells':{},'rows':40,'cols':12,'sheet_name':'Sheet1'}
    rnum=0
    for row in table_node.findall(q(OD_TABLE,'table-row')):
        reps=int(row.attrib.get(q(OD_TABLE,'number-rows-repeated'),'1')); reps=min(reps,500)
        rowvals=[]; cnum=0
        for cell in row.findall(q(OD_TABLE,'table-cell')):
            crep=int(cell.attrib.get(q(OD_TABLE,'number-columns-repeated'),'1')); crep=min(crep,100)
            formula=cell.attrib.get(q(OD_TABLE,'formula'),'')
            value=''.join(cell.itertext())
            if formula: value='='+formula.split(':=',1)[-1].replace('[.','').replace(']','')
            for _ in range(crep): rowvals.append((cnum,value)); cnum+=1
        for _ in range(reps):
            rnum+=1
            for cidx,val in rowvals:
                if val: cells[_cell_ref(cidx,rnum-1)]=val
            if rnum>=500: break
        if rnum>=500:break
    return {'cells':cells,'rows':max(40,rnum),'cols':max(12,max((_col_from_ref(k) for k in cells),default=0)+1),'sheet_name':table_node.attrib.get(q(OD_TABLE,'name'),'Sheet1')}

def _cell_ref(col,row):
    n=col+1;s=''
    while n>0:r=(n-1)%26;s=chr(65+r)+s;n=(n-1)//26
    return s+str(row+1)
def _col_from_ref(ref):
    m=re.match(r'([A-Z]+)',ref); c=0
    for ch in (m.group(1) if m else 'A'):c=c*26+ord(ch)-64
    return c-1

def ods_from_cells(cells,rows=40,cols=12):
    tpl=TPL['ods']; src=zipfile.ZipFile(io.BytesIO(tpl),'r'); root=ET.fromstring(src.read('content.xml')); src.close(); host=root.find('.//'+q(OD_OFFICE,'spreadsheet'))
    for ch in list(host):host.remove(ch)
    tbl=ET.SubElement(host,q(OD_TABLE,'table')); tbl.set(q(OD_TABLE,'name'),'Sheet1')
    used={}; maxr=0;maxc=0
    for ref,val in (cells or {}).items():
        m=re.match(r'^([A-Z]+)(\d+)$',ref.upper());
        if not m:continue
        c=_col_from_ref(ref); r=int(m.group(2))-1; used[(r,c)]=str(val);maxr=max(maxr,r);maxc=max(maxc,c)
    for r in range(maxr+1 if used else 1):
        row=ET.SubElement(tbl,q(OD_TABLE,'table-row'))
        for c in range(maxc+1 if used else 1):
            val=used.get((r,c),''); cell=ET.SubElement(row,q(OD_TABLE,'table-cell'))
            if val.startswith('='):
                formula_body=re.sub(r'(?<![A-Z0-9_])([A-Z]+[0-9]+)(?![A-Z0-9_])',r'[.\1]',val[1:].upper())
                cell.set(q(OD_TABLE,'formula'),'of:='+formula_body)
                cell.set(q(OD_OFFICE,'value-type'),'float')
                cell.set(q(OD_OFFICE,'value'),'0')
            else:
                cell.set(q(OD_OFFICE,'value-type'),'string')
            p=ET.SubElement(cell,q(OD_TEXT,'p'));p.text=val
    return zip_replace(tpl,{'content.xml':ET.tostring(root,encoding='utf-8',xml_declaration=True)},stored_first_mimetype=True)

def odp_to_slides(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z:root=ET.fromstring(z.read('content.xml'))
    slides=[]
    for page in root.findall('.//'+q(OD_DRAW,'page')):
        texts=[]
        for n in page.iter():
            if n.tag in (q(OD_TEXT,'p'),q(OD_TEXT,'h')):
                txt=''.join(n.itertext())
                if txt:texts.append(txt)
        slides.append({'title':texts[0] if texts else '','body':'\n'.join(texts[1:])})
    return slides or [{'title':'','body':''}]

def odp_from_slides(slides):
    tpl=TPL['odp'];src=zipfile.ZipFile(io.BytesIO(tpl),'r');root=ET.fromstring(src.read('content.xml'));src.close();host=root.find('.//'+q(OD_OFFICE,'presentation'));template_page=host.find(q(OD_DRAW,'page'))
    for ch in list(host):host.remove(ch)
    for idx,slide in enumerate(slides or [{'title':'','body':''}],1):
        page=copy.deepcopy(template_page);page.set(q(OD_DRAW,'name'),'page%d'%idx)
        pars=[n for n in page.iter() if n.tag in (q(OD_TEXT,'p'),q(OD_TEXT,'h'))]
        if pars:pars[0].text=str(slide.get('title',''))
        if len(pars)>1:pars[1].text=str(slide.get('body',''))
        for p in pars[2:]:p.text=''
        host.append(page)
    return zip_replace(tpl,{'content.xml':ET.tostring(root,encoding='utf-8',xml_declaration=True)},stored_first_mimetype=True)



def load_json_file(path, default_value):
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            return json.load(handle)
    except Exception:
        return default_value


def save_json_file(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    temp = path + '.tmp-' + uuid.uuid4().hex[:8]
    try:
        with open(temp, 'w', encoding='utf-8') as handle:
            json.dump(data, handle, indent=2, ensure_ascii=False)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass
        os.chmod(temp, 0o600)
        os.replace(temp, path)
    finally:
        try:
            if os.path.exists(temp): os.remove(temp)
        except OSError:
            pass


def now_iso():
    return datetime.now().isoformat(timespec='seconds')


def now_prompt(username, cwd):
    return datetime.now().strftime('%d/%m/%Y-[%H:%M]-(' + username + ')-(' + cwd + ') :')


def strip_ansi(value):
    return ANSI_RE.sub('', value or '')


def active_username(default='DedSec'):
    value = getattr(REQUEST_CONTEXT, 'username', '')
    return str(value or default)


def sanitize_username(value):
    raw = str(value or '').strip()
    cleaned = ''.join(ch for ch in raw if ch.isalnum() or ch in ('-', '_', '.'))[:32]
    return cleaned or 'DedSec'


def user_space_path(username=None):
    return os.path.join(USER_SPACES_DIR, sanitize_username(username or active_username()))


def user_workspace_path(username=None):
    return os.path.join(user_space_path(username), 'workspace')


def user_config_path(username=None):
    return os.path.join(user_space_path(username), 'config.json')


def _normalize_global_profile_state(config):
    merged = dict(config or {})
    profiles = []
    for item in (merged.get('user_profiles') or []):
        raw = str(item or '').strip()
        if not raw:
            continue
        name = sanitize_username(raw)
        if name not in profiles:
            profiles.append(name)
    if not profiles:
        profiles = ['DedSec']
    legacy_candidate = merged.get('active_profile') or merged.get('display_name') or profiles[0]
    active = sanitize_username(legacy_candidate)
    if active not in profiles:
        active = profiles[0]
    merged['user_profiles'] = profiles
    merged['active_profile'] = active
    return merged


def load_global_config():
    config = load_json_file(CONFIG_PATH, {})
    merged = dict(DEFAULT_CONFIG)
    merged.update(config if isinstance(config, dict) else {})
    return _normalize_global_profile_state(merged)


def save_global_config(config):
    merged = dict(DEFAULT_CONFIG)
    merged.update(config or {})
    merged = _normalize_global_profile_state(merged)
    save_json_file(CONFIG_PATH, merged)
    return merged


def _profile_config_seed(username):
    """Seed a user profile without copying global authentication secrets."""
    base = load_global_config()
    for key in AUTH_CONFIG_KEYS:
        base.pop(key, None)
    base.pop('user_profiles', None)
    base.pop('active_profile', None)
    base['display_name'] = sanitize_username(username)
    return base


def ensure_user_space(username=None):
    username = sanitize_username(username or active_username())
    os.makedirs(user_workspace_path(username), exist_ok=True)
    target = user_config_path(username)
    if not os.path.exists(target):
        save_json_file(target, _profile_config_seed(username))
    else:
        # Migrate old builds that copied password/TOTP/recovery secrets into every profile.
        current = load_json_file(target, {})
        if isinstance(current, dict):
            changed = False
            for key in AUTH_CONFIG_KEYS:
                if key in current:
                    current.pop(key, None)
                    changed = True
            if 'user_profiles' in current:
                current.pop('user_profiles', None)
                changed = True
            if 'active_profile' in current:
                current.pop('active_profile', None)
                changed = True
            if changed:
                current['display_name'] = current.get('display_name') or username
                save_json_file(target, current)
    return username


def load_config():
    global_config = load_global_config()
    username = sanitize_username(active_username(global_config.get('active_profile') or 'DedSec'))
    ensure_user_space(username)
    config = load_json_file(user_config_path(username), {})
    merged = dict(DEFAULT_CONFIG)
    merged.update(config if isinstance(config, dict) else {})
    merged['display_name'] = merged.get('display_name') or username
    # Authentication policy is global; profile JSON never owns these values.
    merged['login_enabled'] = bool(global_config.get('login_enabled'))
    merged['totp_enabled'] = bool(global_config.get('totp_enabled'))
    merged['security_questions'] = copy.deepcopy(global_config.get('security_questions') or [])
    merged['user_profiles'] = list(global_config.get('user_profiles') or [])
    merged.pop('active_profile', None)
    merged['password_hash'] = ''
    merged['totp_secret'] = ''
    return merged


def save_config(config):
    global_config = load_global_config()
    # Profile identity is selected globally/session-side. The visible display label must not silently create/switch users.
    username = sanitize_username(active_username(global_config.get('active_profile') or 'DedSec'))
    ensure_user_space(username)
    merged = dict(DEFAULT_CONFIG)
    merged.update(config or {})
    merged['display_name'] = merged.get('display_name') or username
    for key in AUTH_CONFIG_KEYS:
        merged.pop(key, None)
    merged.pop('user_profiles', None)
    merged.pop('active_profile', None)
    save_json_file(user_config_path(username), merged)
    return load_config()


def public_config(config=None):
    merged = dict(load_config() if config is None else config)
    merged.pop('password_hash', None)
    merged.pop('totp_secret', None)
    merged['security_questions'] = [
        {'question': str(item.get('question') or '')}
        for item in (merged.get('security_questions') or [])
        if str(item.get('question') or '').strip()
    ]
    return merged


def authenticated_config_view(config=None):
    """Public settings plus the TOTP setup secret only for an authenticated settings view."""
    result = public_config(load_config() if config is None else config)
    global_config = load_global_config()
    result['login_enabled'] = bool(global_config.get('login_enabled'))
    result['totp_enabled'] = bool(global_config.get('totp_enabled'))
    result['security_questions'] = public_config(global_config).get('security_questions', [])
    if global_config.get('login_enabled') and global_config.get('totp_enabled'):
        result['totp_secret'] = str(global_config.get('totp_secret') or '')
    return result


def collect_device_controls():
    """Return optional Android controls exposed by Termux:API.

    Browser sound is always controlled client-side. Android stream volume and
    brightness are reported separately and only enabled when the corresponding
    Termux:API commands are usable on this device.
    """
    result = {
        'volume_available': False,
        'brightness_available': bool(shutil.which('termux-brightness')),
        'streams': [],
    }
    command = shutil.which('termux-volume')
    if command:
        try:
            proc = subprocess.run([command], capture_output=True, text=True, timeout=4)
            if proc.returncode == 0 and proc.stdout.strip():
                data = json.loads(proc.stdout)
                if isinstance(data, list):
                    clean = []
                    for item in data:
                        if not isinstance(item, dict):
                            continue
                        stream = str(item.get('stream') or '').strip()
                        try:
                            volume = int(item.get('volume', 0))
                            maximum = max(1, int(item.get('max_volume', 1)))
                        except Exception:
                            continue
                        if stream:
                            clean.append({'stream': stream, 'volume': volume, 'max_volume': maximum,
                                          'percent': int(round(volume * 100 / maximum))})
                    result['streams'] = clean
                    result['volume_available'] = bool(clean)
        except Exception:
            pass
    return result


def set_android_media_volume(percent):
    command = shutil.which('termux-volume')
    if not command:
        raise RuntimeError('Android volume control requires Termux:API and the termux-volume command.')
    percent = max(0, min(100, int(round(float(percent)))))
    status = collect_device_controls()
    stream = next((item for item in status.get('streams', []) if item.get('stream') == 'music'), None)
    if not stream:
        stream = next((item for item in status.get('streams', []) if item.get('stream') in {'media','music'}), None)
    if not stream:
        raise RuntimeError('The Android media volume stream is not available.')
    target = int(round(stream['max_volume'] * percent / 100.0))
    proc = subprocess.run([command, str(stream['stream']), str(target)], capture_output=True, text=True, timeout=4)
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or 'termux-volume failed').strip())
    return collect_device_controls()


def set_android_brightness(percent=None, automatic=False):
    command = shutil.which('termux-brightness')
    if not command:
        raise RuntimeError('Android brightness control requires Termux:API and the termux-brightness command.')
    value = 'auto' if automatic else str(max(0, min(255, int(round(float(percent) * 255 / 100.0)))))
    proc = subprocess.run([command, value], capture_output=True, text=True, timeout=4)
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or 'termux-brightness failed').strip())
    return {'brightness_available': True, 'automatic': bool(automatic), 'percent': None if automatic else max(0, min(100, int(round(float(percent)))))}


def _pbkdf2_hash(value, normalized=False, iterations=240000):
    text = str(value or '')
    if normalized:
        text = text.strip().lower()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', text.encode('utf-8'), salt, int(iterations))
    return 'pbkdf2_sha256$%d$%s$%s' % (int(iterations), salt.hex(), digest.hex())


def _pbkdf2_verify(value, encoded, normalized=False):
    text = str(value or '')
    if normalized:
        text = text.strip().lower()
    encoded = str(encoded or '')
    if encoded.startswith('pbkdf2_sha256$'):
        try:
            _kind, iterations, salt_hex, digest_hex = encoded.split('$', 3)
            iterations = max(100000, min(1000000, int(iterations)))
            salt = bytes.fromhex(salt_hex)
            expected = bytes.fromhex(digest_hex)
            actual = hashlib.pbkdf2_hmac('sha256', text.encode('utf-8'), salt, iterations)
            return hmac.compare_digest(actual, expected)
        except Exception:
            return False
    # Compatibility with legacy unsalted SHA-256 values. Successful login/recovery migrates them.
    legacy = hashlib.sha256(text.encode('utf-8')).hexdigest()
    return bool(encoded) and hmac.compare_digest(legacy, encoded)


def hash_password(value):
    return _pbkdf2_hash(value, normalized=False)


def verify_password(value, encoded):
    return _pbkdf2_verify(value, encoded, normalized=False)


def hash_answer(value):
    return _pbkdf2_hash(value, normalized=True)


def verify_answer(value, encoded):
    return _pbkdf2_verify(value, encoded, normalized=True)


def random_base32_secret(length=32):
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    raw = os.urandom(length)
    return ''.join(alphabet[item % len(alphabet)] for item in raw)[:length]


def normalize_totp_secret(secret):
    cleaned = ''.join(ch for ch in str(secret or '').upper() if ch.isalnum())
    return cleaned


def compute_totp_code(secret, for_time=None, step=30, digits=6):
    secret = normalize_totp_secret(secret)
    if not secret:
        return ''
    padding = '=' * ((8 - len(secret) % 8) % 8)
    key = base64.b32decode(secret + padding, casefold=True)
    counter = int((for_time if for_time is not None else time.time()) // step)
    digest = hmac.new(key, struct.pack('>Q', counter), hashlib.sha1).digest()
    offset = digest[-1] & 0x0F
    number = struct.unpack('>I', digest[offset:offset + 4])[0] & 0x7fffffff
    return str(number % (10 ** digits)).zfill(digits)


def build_totp_uri(secret, label='DedSec OS', issuer='DedSec OS'):
    safe_label = urllib.parse.quote(label)
    safe_issuer = urllib.parse.quote(issuer)
    return 'otpauth://totp/' + safe_label + '?secret=' + secret + '&issuer=' + safe_issuer + '&algorithm=SHA1&digits=6&period=30'


def security_questions_configured(config=None):
    cfg = load_global_config() if config is None else config
    items = cfg.get('security_questions') or []
    valid = [item for item in items if str(item.get('question') or '').strip() and str(item.get('answer_hash') or '').strip()]
    return len(valid) >= 3


def is_auth_enabled():
    config = load_global_config()
    return bool(config.get('login_enabled') and config.get('password_hash'))


def parse_cookie_value(header_value):
    cookies = {}
    for chunk in (header_value or '').split(';'):
        if '=' not in chunk:
            continue
        key, value = chunk.split('=', 1)
        cookies[key.strip()] = value.strip()
    return cookies


def request_auth_token(handler):
    cookies = parse_cookie_value(handler.headers.get('Cookie', ''))
    return cookies.get('dedsec_os_auth', '')


def _auth_token_details(token, refresh=False):
    if not token:
        return {}
    with STATE_LOCK:
        details = AUTH_TOKENS.get(token)
        if not isinstance(details, dict):
            return {}
        created = float(details.get('created_at') or details.get('time') or 0)
        if not created or time.time() - created > AUTH_TOKEN_TTL_SECONDS:
            AUTH_TOKENS.pop(token, None)
            return {}
        if refresh:
            details['last_seen'] = time.time()
        return dict(details)


def current_request_username(handler=None):
    token = request_auth_token(handler) if handler is not None else ''
    details = _auth_token_details(token, refresh=True)
    if details.get('username'):
        return sanitize_username(details.get('username'))
    try:
        fallback = load_global_config().get('active_profile') or 'DedSec'
    except Exception:
        fallback = 'DedSec'
    return sanitize_username(fallback)


def is_request_authenticated(handler):
    if not is_auth_enabled():
        return True
    token = request_auth_token(handler)
    return bool(_auth_token_details(token, refresh=True))


def issue_auth_token(username=None):
    token = uuid.uuid4().hex + uuid.uuid4().hex
    now = time.time()
    username = sanitize_username(username or 'DedSec')
    with STATE_LOCK:
        # Bound the in-memory session table for a long-running local server. Expired
        # sessions and the oldest excess sessions for this profile are discarded.
        for existing, details in list(AUTH_TOKENS.items()):
            created = float((details or {}).get('created_at') or (details or {}).get('time') or 0)
            if not created or now - created > AUTH_TOKEN_TTL_SECONDS:
                AUTH_TOKENS.pop(existing, None)
        same_user = sorted(
            [(existing, float((details or {}).get('created_at') or 0)) for existing, details in AUTH_TOKENS.items()
             if sanitize_username((details or {}).get('username')) == username],
            key=lambda item: item[1],
        )
        while len(same_user) >= 8:
            existing, _created = same_user.pop(0)
            AUTH_TOKENS.pop(existing, None)
        AUTH_TOKENS[token] = {'created_at': now, 'last_seen': now, 'username': username}
    return token


def revoke_auth_tokens(username=None, keep_token=''):
    username = sanitize_username(username) if username else ''
    with STATE_LOCK:
        for token, details in list(AUTH_TOKENS.items()):
            if token == keep_token:
                continue
            if not username or sanitize_username((details or {}).get('username')) == username:
                AUTH_TOKENS.pop(token, None)


def clear_auth_token(handler):
    token = request_auth_token(handler)
    if token:
        with STATE_LOCK:
            AUTH_TOKENS.pop(token, None)


def _auth_failure_bucket(kind, scope=''):
    kind = 'recover' if kind == 'recover' else 'login'
    scope = sanitize_username(scope or 'default').casefold()
    return kind + ':' + scope


def auth_rate_limit(kind, scope=''):
    bucket = _auth_failure_bucket(kind, scope); now = time.time()
    with AUTH_FAILURES_LOCK:
        attempts = [stamp for stamp in AUTH_FAILURES.get(bucket, []) if now - stamp < 120]
        AUTH_FAILURES[bucket] = attempts
        if len(attempts) >= 8:
            wait = max(1, int(120 - (now - attempts[0])))
            raise PermissionError('Too many failed attempts for this profile. Try again in %d seconds.' % wait)


def auth_note_failure(kind, scope=''):
    bucket = _auth_failure_bucket(kind, scope)
    with AUTH_FAILURES_LOCK:
        AUTH_FAILURES.setdefault(bucket, []).append(time.time()); AUTH_FAILURES[bucket] = AUTH_FAILURES[bucket][-12:]


def auth_note_success(kind, scope=''):
    bucket = _auth_failure_bucket(kind, scope)
    with AUTH_FAILURES_LOCK: AUTH_FAILURES[bucket] = []


def load_jobs():
    data = load_json_file(JOBS_PATH, {})
    if not isinstance(data, dict):
        data = {}
    return data


def _job_artifact_paths(job):
    paths = []
    for key in ('log_file', 'pid_file', 'exit_file', 'cwd_file'):
        value = str((job or {}).get(key) or '')
        if value:
            paths.append(value)
    job_id = str((job or {}).get('id') or '')
    if job_id and job_id != 'web-shell':
        paths.append(os.path.join(WRAPPERS_DIR, job_id + '.sh'))
    return paths


def _prune_job_history(jobs, max_completed=180):
    """Bound persisted completed-job history without ever discarding running jobs."""
    if not isinstance(jobs, dict):
        return {}
    completed = [
        job for key, job in jobs.items()
        if key != 'web-shell' and isinstance(job, dict) and not job.get('running')
    ]
    completed.sort(key=lambda item: str(item.get('started_at') or ''), reverse=True)
    keep_ids = {str(item.get('id') or '') for item in completed[:max_completed]}
    for key, job in list(jobs.items()):
        if key == 'web-shell' or not isinstance(job, dict) or job.get('running') or key in keep_ids:
            continue
        jobs.pop(key, None)
        for artifact in _job_artifact_paths(job):
            try:
                if os.path.isfile(artifact) or os.path.islink(artifact):
                    os.remove(artifact)
            except OSError:
                pass
        LOCAL_PROCESSES.pop(key, None)
        tty = LOCAL_TTYS.pop(key, None)
        if tty is not None:
            try: os.close(tty)
            except OSError: pass
    return jobs


def save_jobs(jobs):
    save_json_file(JOBS_PATH, jobs)


def ensure_setup():
    for path in (DEDSEC_OS_ROOT, USER_SPACES_DIR, RUNTIME_DIR, LOGS_DIR, WRAPPERS_DIR, PIDS_DIR, EXITS_DIR, WALLPAPERS_DIR, PROFILE_BACKUPS_DIR, TRASH_DIR):
        os.makedirs(path, exist_ok=True)
    if not os.path.exists(CONFIG_PATH):
        save_global_config(DEFAULT_CONFIG)
    ensure_user_space(load_global_config().get('active_profile') or 'DedSec')
    jobs = load_jobs()
    if 'web-shell' not in jobs:
        log_file = os.path.join(LOGS_DIR, 'web-shell.log')
        jobs['web-shell'] = {
            'id': 'web-shell',
            'label': 'Web Shell',
            'command': '',
            'started_at': now_iso(),
            'log_file': log_file,
            'pid_file': '',
            'exit_file': '',
            'running': False,
            'exit_code': 0,
            'real_termux': False,
            'cwd': HOME_DIR,
            'kind': 'web-shell',
            'closed': False
        }
        if not os.path.exists(log_file):
            with open(log_file, 'w', encoding='utf-8') as handle:
                handle.write('DedSec OS Web Shell ready.\n')
    save_jobs(jobs)


def load_language_preference():
    data = load_json_file(LANGUAGE_JSON_PATH, {})
    language = data.get('preferred_language')
    if language in ('english', 'greek'):
        return language
    return 'english'


def save_language_preference_server(language):
    data = load_json_file(LANGUAGE_JSON_PATH, {})
    data['preferred_language'] = language
    save_json_file(LANGUAGE_JSON_PATH, data)


def load_menu_autostart_preference_server():
    data = load_json_file(LANGUAGE_JSON_PATH, {})
    return bool(data.get('menu_autostart', True))


def save_menu_autostart_preference_server(enabled):
    data = load_json_file(LANGUAGE_JSON_PATH, {})
    data['menu_autostart'] = bool(enabled)
    save_json_file(LANGUAGE_JSON_PATH, data)


def load_menu_style_preference():
    data = load_json_file(LANGUAGE_JSON_PATH, {})
    style = data.get('menu_style')
    if style in ('list', 'grid', 'number', 'pipboy', 'dedsec_os'):
        return style
    return None


def save_menu_style_preference(style):
    if style not in ('list', 'grid', 'number', 'pipboy', 'dedsec_os'):
        return False
    data = load_json_file(LANGUAGE_JSON_PATH, {})
    data['menu_style'] = style
    save_json_file(LANGUAGE_JSON_PATH, data)
    return True


def sanitize_prompt_username_server(username):
    """Mirror the outer prompt policy so browser input cannot inject shell syntax."""
    username = (username or '').strip()
    username = re.sub(r"[^A-Za-z0-9_.@-]", "_", username)
    return username[:48] or "DedSec"


def build_dedsec_ps1_server(username):
    username = sanitize_prompt_username_server(username)
    return (
        "PS1='\\[\\e[1;36m\\]\\D{%d/%m/%Y}-[\\A]-(\\[\\e[1;34m\\]"
        + username
        + "\\[\\e[0m\\])-(\\[\\e[1;33m\\]\\W\\[\\e[0m\\]) : '\\n"
    )


def atomic_write_bashrc_server(content):
    """Atomic Bashrc replacement for browser-side Settings actions."""
    directory = os.path.dirname(BASHRC_PATH) or '.'
    os.makedirs(directory, exist_ok=True)
    lock_path = BASHRC_PATH + '.dedsec.lock'
    lock_fd = os.open(lock_path, os.O_CREAT | os.O_RDWR, 0o600)
    temp_path = BASHRC_PATH + f'.tmp-{os.getpid()}-{uuid.uuid4().hex}'
    try:
        fcntl.flock(lock_fd, fcntl.LOCK_EX)
        try:
            mode = stat.S_IMODE(os.stat(BASHRC_PATH).st_mode)
        except OSError:
            mode = 0o600
        with open(temp_path, 'w', encoding='utf-8', newline='') as handle:
            handle.write(str(content))
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_path, mode)
        os.replace(temp_path, BASHRC_PATH)
        try:
            dir_fd = os.open(directory, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except OSError:
            pass
        return True
    finally:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass
        try:
            fcntl.flock(lock_fd, fcntl.LOCK_UN)
        except Exception:
            pass
        os.close(lock_fd)


def get_current_menu_style_server():
    saved_style = load_menu_style_preference()
    if saved_style:
        return saved_style
    try:
        content = open(BASHRC_PATH, 'r', encoding='utf-8').read()
    except Exception:
        return 'list'
    if '--menu pipboy' in content or '--menu ded-guy' in content:
        return 'pipboy'
    if '--menu dedsec_os' in content:
        return 'dedsec_os'
    if '--menu grid' in content:
        return 'grid'
    if '--menu number' in content:
        return 'number'
    return 'list'


def current_language_path_from_pref():
    return GREEK_PATH_FULL if load_language_preference() == 'greek' and os.path.isdir(GREEK_PATH_FULL) else ENGLISH_BASE_PATH


def update_bashrc_server(current_language_path, current_style):
    save_menu_style_preference(current_style)
    try:
        lines = open(BASHRC_PATH, 'r', encoding='utf-8').readlines()
    except Exception:
        lines = []
    filtered = []
    in_block = False
    regex_pattern = re.compile(r"(cd\s+.*DedSec/Scripts.*python3\s+.*Settings\.py\s+--menu.*|alias\s+(m|e|g)=.*cd\s+.*DedSec/Scripts.*)")
    for line in lines:
        if BASHRC_START_MARKER in line or (line.startswith("# --- DedSec ") and "Background Checker" in line):
            in_block = True
            continue
        if BASHRC_END_MARKER in line or (line.startswith("# --- End DedSec ") and "Background Checker" in line):
            in_block = False
            continue
        if in_block:
            continue
        if not regex_pattern.search(line):
            filtered.append(line)
    launch_style = "ded-guy" if current_style == "pipboy" else current_style
    new_startup = f'cd "{current_language_path}" && python3 "{SETTINGS_SCRIPT_PATH}" --menu {launch_style}; cd "{HOME_DIR}"\n'
    alias_lang = ''
    if current_language_path == ENGLISH_BASE_PATH:
        alias_lang = f"alias e='cd \"{ENGLISH_BASE_PATH}\" && python3 \"{SETTINGS_SCRIPT_PATH}\" --menu {launch_style}'\n"
    elif current_language_path == GREEK_PATH_FULL:
        alias_lang = f"alias g='cd \"{GREEK_PATH_FULL}\" && python3 \"{SETTINGS_SCRIPT_PATH}\" --menu {launch_style}'\n"
    filtered.append('\n' + BASHRC_START_MARKER + '\n')
    if load_menu_autostart_preference_server() or current_style in {'pipboy', 'dedsec_os'}:
        filtered.append(new_startup)
    else:
        filtered.append('# (DedSec Menu auto-start disabled; Ded-Guy learning remains enabled)\n')
    if alias_lang:
        filtered.append(alias_lang)
    filtered.append(BASHRC_END_MARKER + '\n')
    atomic_write_bashrc_server(''.join(filtered))


def apply_language_server(language):
    save_language_preference_server(language)
    if language == 'english':
        if os.path.isdir(GREEK_PATH_FULL):
            try:
                os.rename(GREEK_PATH_FULL, HIDDEN_GREEK_PATH)
            except Exception:
                pass
        target = ENGLISH_BASE_PATH
    else:
        if os.path.isdir(HIDDEN_GREEK_PATH):
            try:
                os.rename(HIDDEN_GREEK_PATH, GREEK_PATH_FULL)
            except Exception:
                pass
        os.makedirs(GREEK_PATH_FULL, exist_ok=True)
        target = GREEK_PATH_FULL
    update_bashrc_server(target, get_current_menu_style_server())
    return target


def update_prompt_server(username):
    username = (username or '').strip()
    if not username:
        raise ValueError('Username cannot be empty.')
    username = sanitize_prompt_username_server(username)
    try:
        lines = open(BASHRC_PATH, 'r', encoding='utf-8').readlines()
    except Exception:
        lines = []
    new_ps1 = build_dedsec_ps1_server(username)
    replaced = False
    out = []
    for line in lines:
        if line.strip().startswith('PS1='):
            out.append(new_ps1)
            replaced = True
        else:
            out.append(line)
    if not replaced:
        out.append(new_ps1)
    atomic_write_bashrc_server(''.join(out))


