      ['dedsec','#cd93ff'],['cyan','#57d6ff'],['green','#51cf66'],['amber','#ffb347'],
      ['ice','#8be9fd'],['crimson','#ff5d7a'],['neon','#b8ff4d'],['rose','#ff9ed1'],
