                if not filename:
                    raise ValueError('Upload filename is required.')
                encoded = str(payload.get('data') or '')
                if ',' in encoded and encoded.lower().startswith('data:'):
                    encoded = encoded.split(',', 1)[1]
                raw = base64.b64decode(encoded, validate=True)
