def ensure_dedsec_os_files():
    os.makedirs(DEDSEC_OS_ROOT, exist_ok=True)
    os.makedirs(DEDSEC_OS_RUNTIME_DIR, exist_ok=True)
    if not os.path.exists(DEDSEC_OS_CONFIG_PATH):
        initial_config = {'display_name': 'DedSec', 'active_profile': 'DedSec', 'user_profiles': ['DedSec'], 'wallpaper': '', 'wallpaper_name': '', 'wallpaper_fit': 'cover', 'wallpaper_dim': 0.22, 'wallpaper_blur': 0, 'appearance_mode': 'system', 'terminal_theme': 'dedsec', 'accent_color': '', 'visual_preset': 'dedsec', 'icon_pack': 'xp', 'icon_shape': 'rounded', 'desktop_icon_size': 42, 'window_style': 'xp', 'taskbar_style': 'xp', 'font_family': 'system', 'cursor_style': 'system', 'sound_scheme': 'dedsec', 'panel_opacity': 0.88, 'glass_blur': 14, 'ui_scale': 1.0, 'ui_density': 'comfortable', 'animations_enabled': True, 'interface_mode': 'auto', 'desktop_icons': True, 'taskbar_position': 'bottom', 'taskbar_autohide': False, 'startup_apps': [], 'clock_24h': True, 'ui_sounds': True, 'notification_sounds': True, 'master_volume': 0.85, 'android_media_volume_percent': 70, 'android_brightness_percent': 55, 'login_enabled': False, 'password_hash': '', 'totp_enabled': False, 'totp_secret': '', 'security_questions': []}
        config_temp = DEDSEC_OS_CONFIG_PATH + f'.tmp-{os.getpid()}-{threading.get_ident()}'
        with open(config_temp, 'w', encoding='utf-8') as handle:
            json.dump(initial_config, handle, indent=4, ensure_ascii=False)
            handle.flush(); os.fsync(handle.fileno())
        os.chmod(config_temp, 0o600)
        os.replace(config_temp, DEDSEC_OS_CONFIG_PATH)
    else:
        try: os.chmod(DEDSEC_OS_CONFIG_PATH, 0o600)
        except OSError: pass
    server_source = dedsec_os_server_source()
    server_temp = DEDSEC_OS_SERVER_PATH + f'.tmp-{os.getpid()}-{threading.get_ident()}'
    with open(server_temp, 'w', encoding='utf-8') as handle:
        handle.write(server_source)
        handle.flush(); os.fsync(handle.fileno())
    os.chmod(server_temp, 0o700)
    os.replace(server_temp, DEDSEC_OS_SERVER_PATH)
    return DEDSEC_OS_SERVER_PATH


def find_free_local_port(start_port=DEDSEC_OS_DEFAULT_PORT, end_port=18949):
    for port in range(start_port, end_port + 1):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if sock.connect_ex(('127.0.0.1', port)) != 0:
                return port
    raise RuntimeError('No free local port available for DedSec OS.')


def is_port_listening(port):
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.5)
        return sock.connect_ex(('127.0.0.1', port)) == 0


def _dedsec_os_process_start_ticks(pid):
    try:
        with open('/proc/' + str(int(pid)) + '/stat', 'r', encoding='utf-8', errors='replace') as handle:
            data = handle.read()
        end = data.rfind(')')
        fields = data[end + 2:].split() if end >= 0 else []
        return int(fields[19]) if len(fields) > 19 else 0
    except Exception:
        return 0


def _dedsec_os_process_matches(pid, expected_start_ticks=0):
    try:
        pid = int(pid)
        if pid <= 1:
            return False
        if os.stat('/proc/' + str(pid)).st_uid != os.getuid():
            return False
        cmdline = open('/proc/' + str(pid) + '/cmdline', 'rb').read(32768).replace(b'\x00', b' ').decode('utf-8', 'replace')
        if os.path.realpath(DEDSEC_OS_SERVER_PATH) not in cmdline:
            return False
        if expected_start_ticks:
            return _dedsec_os_process_start_ticks(pid) == int(expected_start_ticks)
        return True
    except Exception:
        return False


def _rotate_dedsec_os_log():
    try:
        if os.path.isfile(DEDSEC_OS_LOG_PATH) and os.path.getsize(DEDSEC_OS_LOG_PATH) > 5 * 1024 * 1024:
            rotated = DEDSEC_OS_LOG_PATH + '.1'
            try:
                if os.path.exists(rotated): os.remove(rotated)
            except Exception:
                pass
            os.replace(DEDSEC_OS_LOG_PATH, rotated)
    except Exception:
        pass


def open_local_url(url):
    commands = []
    if shutil.which('termux-open-url'):
        commands.append(['termux-open-url', url])
    if shutil.which('am') or os.path.exists('/system/bin/am'):
        am_bin = shutil.which('am') or '/system/bin/am'
        commands.append([am_bin, 'start', '--user', '0', '-a', 'android.intent.action.VIEW', '-d', url])
    if shutil.which('xdg-open'):
        commands.append(['xdg-open', url])
    for command in commands:
        try:
            result = subprocess.run(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=8)
            if result.returncode == 0:
                return True
        except Exception:
            continue
    return False


def launch_dedsec_os():
    print('[+] Launching DedSec OS...')
    server_path = ensure_dedsec_os_files()
    current_hash = hashlib.sha256(open(server_path, 'rb').read()).hexdigest()

    existing_state = {}
    if os.path.exists(DEDSEC_OS_STATE_PATH):
        try:
            with open(DEDSEC_OS_STATE_PATH, 'r', encoding='utf-8') as handle:
                existing_state = json.load(handle)
        except Exception:
            existing_state = {}

    existing_pid = int(existing_state.get('pid', 0) or 0)
    existing_port = int(existing_state.get('port', 0) or 0)
    existing_hash = existing_state.get('server_hash')
    existing_start_ticks = int(existing_state.get('start_ticks', 0) or 0)
    existing_matches = _dedsec_os_process_matches(existing_pid, existing_start_ticks) if existing_pid else False

    if existing_matches and existing_port and is_port_listening(existing_port) and existing_hash == current_hash:
        url = 'http://127.0.0.1:' + str(existing_port)
        browser_url = url + '/?v=' + str(int(time.time()))
        print('[+] DedSec OS server already running at: ' + url)
        open_local_url(browser_url)
        print('[+] Termux remains locked until login in the web interface or a menu style change unlocks it.')
        for _ in range(60 * 60 * 8):
            if os.path.exists(DEDSEC_OS_UNLOCK_FLAG_PATH):
                try:
                    os.remove(DEDSEC_OS_UNLOCK_FLAG_PATH)
                except Exception:
                    pass
                break
            time.sleep(1)
        return url

    if existing_matches:
        try:
            os.kill(existing_pid, signal.SIGTERM)
            deadline = time.monotonic() + 3.0
            while time.monotonic() < deadline and _dedsec_os_process_matches(existing_pid, existing_start_ticks):
                time.sleep(0.05)
            if _dedsec_os_process_matches(existing_pid, existing_start_ticks):
                os.kill(existing_pid, signal.SIGKILL)
        except Exception:
            pass

    port = find_free_local_port()
    _rotate_dedsec_os_log()
    server_log_handle = open(DEDSEC_OS_LOG_PATH, 'a', encoding='utf-8')
    process = subprocess.Popen(
        ['python3', server_path, str(port)],
        cwd=DEDSEC_OS_ROOT,
        stdout=server_log_handle,
        stderr=server_log_handle,
        stdin=subprocess.DEVNULL,
        start_new_session=True,
    )
    server_log_handle.close()
    start_ticks = 0
    for _attempt in range(20):
        start_ticks = _dedsec_os_process_start_ticks(process.pid)
        if start_ticks or process.poll() is not None:
            break
        time.sleep(0.01)
    pid_temp = DEDSEC_OS_PID_PATH + '.tmp-' + uuid.uuid4().hex[:8]
    with open(pid_temp, 'w', encoding='utf-8') as handle:
        handle.write(str(process.pid))
        handle.flush()
        try: os.fsync(handle.fileno())
        except Exception: pass
    os.replace(pid_temp, DEDSEC_OS_PID_PATH)
    state_temp = DEDSEC_OS_STATE_PATH + '.tmp-' + uuid.uuid4().hex[:8]
    with open(state_temp, 'w', encoding='utf-8') as handle:
        json.dump({'pid': process.pid, 'port': port, 'server_hash': current_hash, 'start_ticks': start_ticks}, handle)
        handle.flush()
        try: os.fsync(handle.fileno())
        except Exception: pass
    os.replace(state_temp, DEDSEC_OS_STATE_PATH)
    url = 'http://127.0.0.1:' + str(port)
    started = False
    # Allow up to 60 seconds for DedSec OS to finish initialization and bind its localhost port.
    for _ in range(400):
        if process.poll() is not None:
            break
        if is_port_listening(port):
            started = True
            break
        time.sleep(0.15)
    if not started:
        try:
            if process.poll() is None:
                process.terminate()
                try: process.wait(timeout=2)
                except subprocess.TimeoutExpired: process.kill()
        except Exception:
            pass
        for stale in (DEDSEC_OS_PID_PATH, DEDSEC_OS_STATE_PATH):
            try:
                if os.path.exists(stale): os.remove(stale)
            except OSError:
                pass
        raise RuntimeError('DedSec OS local server failed to start. Check ' + DEDSEC_OS_LOG_PATH)
    if os.path.exists(DEDSEC_OS_UNLOCK_FLAG_PATH):
        try:
            os.remove(DEDSEC_OS_UNLOCK_FLAG_PATH)
        except Exception:
            pass
    browser_url = url + '/?v=' + str(int(time.time()))
    browser_opened = open_local_url(browser_url)
    print('[+] DedSec OS server running at: ' + url)
    if not browser_opened:
        print('[+] Open this URL in your browser: ' + browser_url)
    print('[+] Termux remains locked until login in the web interface or a menu style change unlocks it.')
    for _ in range(60 * 60 * 8):
        if os.path.exists(DEDSEC_OS_UNLOCK_FLAG_PATH):
            try:
                os.remove(DEDSEC_OS_UNLOCK_FLAG_PATH)
            except Exception:
                pass
            break
        if process.poll() is not None:
            break
        time.sleep(1)
    return url



# ------------------------------
# HTTP Proxy / Tor Utilities
# ------------------------------
def network_ensure_dirs():
    try:
        os.makedirs(NETWORK_DATA_DIR, exist_ok=True)
        os.makedirs(NETWORK_TOR_DATA_DIR, exist_ok=True)
    except Exception:
        pass


def network_load_json(path, default_value):
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
                return data
    except Exception:
        pass
    return default_value


def network_save_json(path, data):
    network_ensure_dirs()
    temp_path = path + ".tmp-" + str(os.getpid()) + "-" + str(threading.get_ident())
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(data, handle, indent=2, ensure_ascii=False)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_path, 0o600)
        os.replace(temp_path, path)
    except Exception:
        try:
            if os.path.exists(temp_path):
                os.remove(temp_path)
        except OSError:
            pass


def network_default_config():
    return {
        "tor_enabled": False,
        "proxy_enabled": False,
        "country": "US",
        "proxy": "",
        "last_proxy_refresh": 0,
        "last_tools_update": 0,
    }


def network_normalize_proxy(proxy):
    """Return a safe public HTTP(S) proxy URL or an empty string.

    Proxy-list APIs are untrusted network input.  Only literal public IP
    addresses and numeric TCP ports are accepted so values later written to
    bash.bashrc cannot inject shell syntax or redirect traffic into localhost.
    """
    value = str(proxy or "").strip()
    if not value:
        return ""
    try:
        parsed = urlparse(value)
        scheme = (parsed.scheme or "").lower()
        if scheme not in {"http", "https"} or parsed.username or parsed.password:
            return ""
        host = parsed.hostname
        port = parsed.port
        if not host or port is None or not (1 <= int(port) <= 65535):
            return ""
        address = ipaddress.ip_address(host)
        if (
            address.is_private or address.is_loopback or address.is_link_local
            or address.is_multicast or address.is_unspecified or address.is_reserved
        ):
            return ""
        host_text = "[" + address.compressed + "]" if address.version == 6 else address.compressed
        return f"{scheme}://{host_text}:{int(port)}"
    except (ValueError, TypeError):
        return ""


def network_load_config():
    config = network_default_config()
    saved = network_load_json(NETWORK_CONFIG_PATH, {})
    if isinstance(saved, dict):
        config.update(saved)
        if 'proxy_enabled' not in saved and 'vpn_enabled' in saved:
            config['proxy_enabled'] = bool(saved.get('vpn_enabled'))
    country = str(config.get("country") or "US").upper()
    if country not in NETWORK_COUNTRIES:
        country = "US"
    config["country"] = country
    config["tor_enabled"] = bool(config.get("tor_enabled", False))
    config["proxy_enabled"] = bool(config.get("proxy_enabled", False))
    config["proxy"] = network_normalize_proxy(config.get("proxy"))
    return config


def network_save_config(config):
    clean = network_default_config()
    if isinstance(config, dict):
        clean.update(config)
    clean["country"] = str(clean.get("country") or "US").upper()
    clean["tor_enabled"] = bool(clean.get("tor_enabled", False))
    clean["proxy_enabled"] = bool(clean.get("proxy_enabled", False))
    clean["proxy"] = network_normalize_proxy(clean.get("proxy"))
    network_save_json(NETWORK_CONFIG_PATH, clean)


def network_run(command, capture=False, timeout=600):
    try:
        return subprocess.run(
            command,
            check=False,
            text=True,
            stdout=subprocess.PIPE if capture else None,
            stderr=subprocess.STDOUT if capture else None,
            timeout=timeout,
        )
    except Exception:
        return None


def network_is_termux():
    prefix = os.environ.get("PREFIX", "")
    return "com.termux" in prefix or "TERMUX_VERSION" in os.environ or os.path.isdir("/data/data/com.termux")


def network_install_python_package(package_name):
    result = network_run([sys.executable, "-m", "pip", "install", "--upgrade", package_name], capture=True)
    return bool(result and result.returncode == 0)


def network_update_tools(silent=False):
    messages = []
    if network_is_termux() and shutil.which("pkg"):
        if not silent:
            print("[*] pkg update ...")
        network_run(["pkg", "update", "-y"])
        network_run(["pkg", "install", "-y", "tor", "openssl", "curl", "wget"])
        messages.append("Termux packages checked")
    if not network_pysocks_available():
        if not silent:
            print("[*] Installing PySocks ...")
        if network_install_python_package("pysocks"):
            messages.append("PySocks checked")
    if not silent:
        print(_("Network tools checked."))
    config = network_load_config()
    config["last_tools_update"] = int(time.time())
    network_save_config(config)
    if not silent:
        try:
            pipboy_refresh_knowledge_after_update(
                trigger="network_tools_update", force_project_rebuild=False, quiet=False
            )
        except Exception as exc:
            try:
                pipboy_log_error("network tools knowledge refresh", exc)
            except Exception:
                pass
            print(pipboy_text(
                f"[!] Network tools were updated, but the Ded-Guy database check failed: {exc}",
                f"[!] Τα εργαλεία δικτύου ενημερώθηκαν, αλλά ο έλεγχος βάσης Ded-Guy απέτυχε: {exc}",
            ))
    return messages


def network_local_port_open(host, port, timeout=0.5):
    try:
        with socket.create_connection((host, port), timeout=timeout):
            return True
    except Exception:
        return False


def network_tor_binary():
    return shutil.which("tor")


def network_pysocks_available():
    try:
        __import__("socks")
        return True
    except Exception:
        return False


def network_read_tor_pid():
    try:
        with open(NETWORK_TOR_PID_PATH, "r", encoding="utf-8") as handle:
            pid = int(handle.read().strip())
        return pid if pid > 1 else None
    except Exception:
        return None


def network_tor_pid_matches(pid):
    try:
        pid = int(pid)
        if pid <= 1:
            return False
        with open(f"/proc/{pid}/cmdline", "rb") as handle:
            command = handle.read(65536).replace(b"\x00", b" ").decode("utf-8", errors="replace")
        return (
            "tor" in os.path.basename(command.split()[0]).casefold()
            and ("127.0.0.1:" + str(NETWORK_TOR_SOCKS_PORT)) in command
            and NETWORK_TOR_DATA_DIR in command
        )
    except Exception:
        return False


def network_write_tor_pid(pid):
    network_ensure_dirs()
    temp = NETWORK_TOR_PID_PATH + ".tmp"
    try:
        with open(temp, "w", encoding="utf-8") as handle:
            handle.write(str(int(pid)))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, NETWORK_TOR_PID_PATH)
    except Exception:
        try:
            if os.path.exists(temp):
                os.remove(temp)
        except OSError:
            pass


def network_clear_tor_pid(expected_pid=None):
    try:
        current = network_read_tor_pid()
        if expected_pid is None or current == int(expected_pid):
            if os.path.exists(NETWORK_TOR_PID_PATH):
                os.remove(NETWORK_TOR_PID_PATH)
    except Exception:
        pass


def network_tor_running():
    global NETWORK_TOR_PROCESS
    if NETWORK_TOR_PROCESS is not None:
        if NETWORK_TOR_PROCESS.poll() is None and network_tor_pid_matches(NETWORK_TOR_PROCESS.pid):
            return network_local_port_open("127.0.0.1", NETWORK_TOR_SOCKS_PORT)
        if NETWORK_TOR_PROCESS.poll() is not None:
            network_clear_tor_pid(NETWORK_TOR_PROCESS.pid)
        NETWORK_TOR_PROCESS = None
    stored_pid = network_read_tor_pid()
    if stored_pid and network_tor_pid_matches(stored_pid):
        return network_local_port_open("127.0.0.1", NETWORK_TOR_SOCKS_PORT)
    if stored_pid:
        network_clear_tor_pid(stored_pid)
    return False


def network_install_tor_support(silent=False, allow_install=True):
    if (not network_tor_binary() or not network_pysocks_available()) and allow_install:
        network_update_tools(silent=silent)
    if not network_tor_binary():
        return False, "Tor binary not found. In Termux run: pkg install tor"
    if not network_pysocks_available():
        return False, "PySocks is missing. Run: pip install pysocks"
    return True, _("Tor support ready.")

def network_start_tor(silent=False, allow_install=True):
    global NETWORK_TOR_PROCESS
    ok, msg = network_install_tor_support(silent=silent, allow_install=allow_install)
    if not ok:
        return False, msg
    if network_tor_running():
        return True, _("Tor is already running.")
    log_handle = None
    try:
        network_ensure_dirs()
        log_handle = open(NETWORK_TOR_LOG_PATH, "ab")
        NETWORK_TOR_PROCESS = subprocess.Popen(
            [
                network_tor_binary(),
                "--SocksPort", "127.0.0.1:" + str(NETWORK_TOR_SOCKS_PORT),
                "--DataDirectory", NETWORK_TOR_DATA_DIR,
            ],
            stdout=log_handle,
            stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL,
            close_fds=True,
            start_new_session=True,
        )
        network_write_tor_pid(NETWORK_TOR_PROCESS.pid)
        log_handle.close()
        log_handle = None
        for _attempt_index in range(60):
            if network_tor_running():
                return True, _("Tor started on 127.0.0.1:9050.")
            if NETWORK_TOR_PROCESS and NETWORK_TOR_PROCESS.poll() is not None:
                break
            time.sleep(0.5)
        process = NETWORK_TOR_PROCESS
        if process and process.poll() is None and network_tor_pid_matches(process.pid):
            try:
                process.terminate()
                process.wait(timeout=5)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass
        if process:
            network_clear_tor_pid(process.pid)
        NETWORK_TOR_PROCESS = None
        return False, "Tor did not finish bootstrapping. Check " + NETWORK_TOR_LOG_PATH
    except Exception as error:
        if NETWORK_TOR_PROCESS is not None:
            network_clear_tor_pid(NETWORK_TOR_PROCESS.pid)
        NETWORK_TOR_PROCESS = None
        return False, "Could not start Tor: " + str(error)
    finally:
        if log_handle is not None:
            try:
                log_handle.close()
            except Exception:
                pass

def network_stop_tor():
    global NETWORK_TOR_PROCESS
    stopped = False
    candidate_pid = None
    if NETWORK_TOR_PROCESS and NETWORK_TOR_PROCESS.poll() is None:
        candidate_pid = NETWORK_TOR_PROCESS.pid
    else:
        candidate_pid = network_read_tor_pid()

    if candidate_pid and network_tor_pid_matches(candidate_pid):
        try:
            os.kill(int(candidate_pid), signal.SIGTERM)
            deadline = time.time() + 5
            while time.time() < deadline:
                if not network_tor_pid_matches(candidate_pid):
                    break
                time.sleep(0.1)
            if network_tor_pid_matches(candidate_pid):
                os.kill(int(candidate_pid), signal.SIGKILL)
            stopped = True
        except (ProcessLookupError, PermissionError, OSError):
            stopped = not network_tor_pid_matches(candidate_pid)
    network_clear_tor_pid(candidate_pid)
    NETWORK_TOR_PROCESS = None
    if stopped:
        return True, _("Tor stopped.")
    return False, _("Tor was not started by this app.")

def network_tor_proxy():
    return "socks5h://127.0.0.1:" + str(NETWORK_TOR_SOCKS_PORT)


def network_fetch_proxies_from_proxyscrape_v4(country):
    params = {
        "request": "display_proxies",
        "proxy_format": "protocolipport",
        "format": "json",
        "protocol": "http",
        "timeout": 10000,
        "country": (country or "all").lower(),
        "anonymity": "elite",
    }
    out = []
    try:
        response = requests.get("https://api.proxyscrape.com/v4/free-proxy-list/get", params=params, timeout=12)
        data = response.json()
        for item in data.get("proxies", [])[:80]:
            ip = item.get("ip")
            port = item.get("port")
            proto = item.get("protocol") or "http"
            if ip and port and proto in ("http", "https"):
                out.append(proto + "://" + str(ip) + ":" + str(port))
    except Exception:
        pass
    return out


def network_fetch_proxies_from_proxyscrape_legacy(country):
    params = {
        "protocol": "http",
        "country": str(country or "US").upper(),
        "anonymity": "elite",
        "timeout": 10000,
        "format": "json",
    }
    out = []
    try:
        response = requests.get(NETWORK_PROXY_API, params=params, timeout=12)
        data = response.json()
        for item in data.get("proxies", [])[:60]:
            ip = item.get("ip")
            port = item.get("port")
            proto = item.get("protocol") or "http"
            if ip and port and proto in ("http", "https"):
                out.append(proto + "://" + str(ip) + ":" + str(port))
    except Exception:
        pass
    return out


def network_fetch_proxies_from_geonode(country):
    params = {
        "limit": 80,
        "page": 1,
        "sort_by": "lastChecked",
        "sort_type": "desc",
        "filterLastChecked": 90,
        "country": str(country or "US").upper(),
        "protocols": "http,https",
    }
    out = []
    try:
        response = requests.get("https://proxylist.geonode.com/api/proxy-list", params=params, timeout=12)
        data = response.json()
        for item in data.get("data", [])[:80]:
            ip = item.get("ip")
            port = item.get("port")
            protocols = item.get("protocols") or []
            proto = "https" if "https" in protocols else "http"
            if ip and port:
                out.append(proto + "://" + str(ip) + ":" + str(port))
    except Exception:
        pass
    return out


def network_load_proxy_state():
    state = network_load_json(NETWORK_PROXY_STATE_FILE, {})
    return state if isinstance(state, dict) else {}


def network_save_proxy_state(state):
    network_save_json(NETWORK_PROXY_STATE_FILE, state)


def network_get_bad_proxy_map(country):
    key = str(country or "US").upper()
    state = network_load_proxy_state()
    bucket = state.get(key, {}) if isinstance(state.get(key, {}), dict) else {}
    now = int(time.time())
    cleaned = {}
    for proxy, expiry in bucket.items():
        try:
            if int(expiry) > now:
                cleaned[proxy] = int(expiry)
        except Exception:
            pass
    if cleaned != bucket:
        if cleaned:
            state[key] = cleaned
        elif key in state:
            del state[key]
        network_save_proxy_state(state)
    return cleaned


def network_mark_proxy_bad(country, proxy, ttl=NETWORK_BAD_PROXY_TTL):
    if not proxy:
        return
    state = network_load_proxy_state()
    key = str(country or "US").upper()
    bucket = state.setdefault(key, {})
    bucket[proxy] = int(time.time()) + int(ttl)
    network_save_proxy_state(state)


def network_mark_proxy_good(country, proxy):
    state = network_load_proxy_state()
    key = str(country or "US").upper()
    bucket = state.get(key, {})
    if proxy in bucket:
        del bucket[proxy]
        if bucket:
            state[key] = bucket
        elif key in state:
            del state[key]
        network_save_proxy_state(state)


def network_is_proxy_marked_bad(country, proxy):
    if not proxy:
        return True
    return proxy in network_get_bad_proxy_map(country)


def network_fetch_proxy_pool(country, force_refresh=False):
    network_ensure_dirs()
    cache = network_load_json(NETWORK_PROXY_CACHE_FILE, {})
    key = str(country or "US").upper()
    now = int(time.time())
    cached = cache.get(key) if isinstance(cache, dict) else None
    gathered = []

    if (not force_refresh) and cached and now - int(cached.get("ts", 0)) < NETWORK_PROXY_CACHE_TTL:
        gathered = cached.get("items", [])
    else:
        seen = set()
        for loader in (network_fetch_proxies_from_proxyscrape_v4, network_fetch_proxies_from_geonode, network_fetch_proxies_from_proxyscrape_legacy):
            for proxy in loader(key):
                if proxy and proxy not in seen:
                    seen.add(proxy)
                    gathered.append(proxy)
        if isinstance(cache, dict):
            cache[key] = {"ts": now, "items": gathered}
            network_save_json(NETWORK_PROXY_CACHE_FILE, cache)

    normalized = []
    seen_normalized = set()
    for proxy in gathered:
        safe_proxy = network_normalize_proxy(proxy)
        if safe_proxy and safe_proxy not in seen_normalized:
            seen_normalized.add(safe_proxy)
            normalized.append(safe_proxy)
    bad = network_get_bad_proxy_map(key)
    clean = [proxy for proxy in normalized if proxy not in bad]
    return clean


def network_test_proxy(proxy):
    proxy = network_normalize_proxy(proxy)
    if not proxy:
        return False
    try:
        response = requests.get(
            "https://api.ipify.org",
            timeout=7,
            proxies={"http": proxy, "https": proxy},
            headers={"User-Agent": "DedSec Settings Network Check/1.0"},
        )
        return response.status_code == 200 and bool(response.text.strip())
    except Exception:
        return False


def network_select_working_proxy(country, force_refresh=False, silent=False):
    pool = network_fetch_proxy_pool(country, force_refresh=force_refresh)
    if not pool:
        return "", _("No working proxy found for this country right now. Try renew or choose another location.")
    tests = 0
    for proxy in pool:
        tests += 1
        if not silent:
            print("[*] Testing HTTP proxy " + str(tests) + "/" + str(min(len(pool), NETWORK_MAX_PROXY_TESTS)) + " ...")
        if network_test_proxy(proxy):
            network_mark_proxy_good(country, proxy)
            return proxy, _("HTTP proxy ready") + ": " + proxy
        network_mark_proxy_bad(country, proxy)
        if tests >= NETWORK_MAX_PROXY_TESTS:
            break

    return "", _("No working proxy found for this country right now. Try renew or choose another location.")


def network_remove_bashrc_export_block(content):
    pattern = re.compile(
        re.escape(NETWORK_BASHRC_START_MARKER) + r".*?" + re.escape(NETWORK_BASHRC_END_MARKER) + r"\n?",
        re.DOTALL,
    )
    return pattern.sub("", content)


def network_apply_bashrc_exports():
    """Write HTTP Proxy/Tor proxy exports and a new-session guard into bash.bashrc.

    New shells cannot inherit variables from the already-running Settings.py
    process, so this writes the current proxy state into bash.bashrc. It also
    installs a small shell guard that quietly starts Tor again when Tor is
    enabled and a new Termux session opens. Tor takes priority over the HTTP
    proxy because it is the safer route when both are enabled.
    """
    config = network_load_config()
    try:
        os.makedirs(os.path.dirname(BASHRC_PATH), exist_ok=True)
        if os.path.exists(BASHRC_PATH):
            with open(BASHRC_PATH, "r", encoding="utf-8") as handle:
                content = handle.read()
        else:
            content = ""
        content = network_remove_bashrc_export_block(content).rstrip() + "\n\n"

        exports = [
            'export NO_PROXY="127.0.0.1,localhost,::1"',
            'export no_proxy="127.0.0.1,localhost,::1"',
        ]
        if config.get("tor_enabled"):
            tor_proxy = network_tor_proxy()
            exports.extend([
                'export ALL_PROXY="' + tor_proxy + '"',
                'export all_proxy="' + tor_proxy + '"',
                'export HTTP_PROXY="' + tor_proxy + '"',
                'export HTTPS_PROXY="' + tor_proxy + '"',
                'export http_proxy="' + tor_proxy + '"',
                'export https_proxy="' + tor_proxy + '"',
                'export DEDSEC_NETWORK_MODE="tor"',
            ])
        elif config.get("proxy_enabled") and config.get("proxy"):
            proxy = str(config.get("proxy"))
            exports.extend([
                'export HTTP_PROXY="' + proxy + '"',
                'export HTTPS_PROXY="' + proxy + '"',
                'export http_proxy="' + proxy + '"',
                'export https_proxy="' + proxy + '"',
                "unset ALL_PROXY",
                "unset all_proxy",
                'export DEDSEC_NETWORK_MODE="proxy"',
            ])
        else:
            exports.extend([
                "unset HTTP_PROXY",
                "unset HTTPS_PROXY",
                "unset http_proxy",
                "unset https_proxy",
                "unset ALL_PROXY",
                "unset all_proxy",
                'export DEDSEC_NETWORK_MODE="off"',
            ])

        safe_settings_path = SETTINGS_SCRIPT_PATH.replace('"', '\\"')
        guard_lines = [
            'DEDSEC_NETWORK_SETTINGS="' + safe_settings_path + '"',
            "DEDSEC_NETWORK_LAST=0",
            "dedsec_network_session_guard() {",
            "    local now=\"$(date +%s 2>/dev/null || echo 0)\"",
            "    local interval=\"" + str(NETWORK_SESSION_GUARD_INTERVAL_SECONDS) + "\"",
            "    if [ -z \"$now\" ]; then now=0; fi",
            "    if [ -z \"$DEDSEC_NETWORK_LAST\" ]; then DEDSEC_NETWORK_LAST=0; fi",
            "    if [ $((now - DEDSEC_NETWORK_LAST)) -ge $interval ]; then",
            "        DEDSEC_NETWORK_LAST=\"$now\"",
            "        if [ -f \"$DEDSEC_NETWORK_SETTINGS\" ]; then",
            "            (python3 \"$DEDSEC_NETWORK_SETTINGS\" " + NETWORK_SESSION_GUARD_COMMAND + " >/dev/null 2>&1 &)",
            "        fi",
            "    fi",
            "}",
            "dedsec_network_session_guard",
            "case \"$PROMPT_COMMAND\" in",
            "    *dedsec_network_session_guard*) ;;",
            "    *) PROMPT_COMMAND=\"dedsec_network_session_guard${PROMPT_COMMAND:+;$PROMPT_COMMAND}\" ;;",
            "esac",
        ]

        block = NETWORK_BASHRC_START_MARKER + "\n" + "\n".join(exports + guard_lines) + "\n" + NETWORK_BASHRC_END_MARKER + "\n"
        atomic_write_bashrc(content + block)
    except Exception as error:
        print("[!] Failed to update network exports: " + str(error))

def network_status_lines():
    config = network_load_config()
    country = config.get("country", "US")
    lines = [
        _("Tor Connection") + ": " + (_("Enabled") if config.get("tor_enabled") else _("Disabled")) + " / " + (_("Running") if network_tor_running() else _("Stopped")),
        _("HTTP Proxy Connection") + ": " + (_("Enabled") if config.get("proxy_enabled") else _("Disabled")),
        _("Country") + ": " + country + " - " + NETWORK_COUNTRIES.get(country, country),
        _("Current proxy") + ": " + (config.get("proxy") or _("No proxy selected")),
        _("New sessions") + ": " + _("Covered by bash.bashrc hook"),
    ]
    return lines


def network_print_status():
    print("=== " + _("Network Utilities") + " ===")
    for line in network_status_lines():
        print(line)


def network_enable_tor():
    config = network_load_config()
    ok, msg = network_start_tor(silent=False)
    if ok:
        config["tor_enabled"] = True
        # Tor takes priority over the HTTP proxy because it is more private when active.
        network_save_config(config)
        network_apply_bashrc_exports()
    print(msg)
    if ok:
        print(_("Network exports updated. Restart Termux or open a new shell to apply them everywhere."))


def network_disable_tor():
    config = network_load_config()
    ok, msg = network_stop_tor()
    config["tor_enabled"] = False
    network_save_config(config)
    network_apply_bashrc_exports()
    print(msg)
    print(_("Network exports updated. Restart Termux or open a new shell to apply them everywhere."))


def network_enable_http_proxy(force_refresh=False):
    config = network_load_config()
    country = config.get("country", "US")
    existing_proxy = str(config.get("proxy") or "").strip()

    # Do not test the saved proxy every time. Reuse it unless the user renews
    # proxies, changes country, has no saved proxy, or it was previously marked bad.
    if existing_proxy and not force_refresh and not network_is_proxy_marked_bad(country, existing_proxy):
        config["proxy_enabled"] = True
        config["proxy"] = existing_proxy
        network_save_config(config)
        network_apply_bashrc_exports()
        print(_("HTTP proxy ready") + ": " + existing_proxy)
        print(_("Saved HTTP Proxy proxy reused without retesting."))
        print(_("Network exports updated. Restart Termux or open a new shell to apply them everywhere."))
        return

    if existing_proxy and network_is_proxy_marked_bad(country, existing_proxy):
        print(_("Saved proxy was previously marked as bad. Searching for a new one."))

    proxy, msg = network_select_working_proxy(country, force_refresh=force_refresh, silent=False)
    if proxy:
        config["proxy_enabled"] = True
        config["proxy"] = proxy
        config["last_proxy_refresh"] = int(time.time())
        network_save_config(config)
        network_apply_bashrc_exports()
    print(msg)
    if proxy:
        print(_("Network exports updated. Restart Termux or open a new shell to apply them everywhere."))


def network_disable_http_proxy():
    config = network_load_config()
    config["proxy_enabled"] = False
    config["proxy"] = ""
    network_save_config(config)
    network_apply_bashrc_exports()
    print(_("HTTP Proxy Connection") + ": " + _("Disabled"))
    print(_("Network exports updated. Restart Termux or open a new shell to apply them everywhere."))


def network_choose_proxy_location():
    config = network_load_config()
    countries = sorted(NETWORK_COUNTRIES.items(), key=lambda item: item[1].lower())
    print("=== " + _("Choose HTTP Proxy Location") + " ===")
    for index, (code, name) in enumerate(countries, start=1):
        current = " *" if code == config.get("country") else ""
        print(str(index) + ". " + code + " - " + name + current)
    choice = input(_("Enter the number of your choice: ")).strip()
    try:
        selected_index = int(choice) - 1
        if selected_index < 0 or selected_index >= len(countries):
            raise ValueError()
    except Exception:
        print(_("Invalid selection. Please try again."))
        return

    country_code, country_name = countries[selected_index]
    config["country"] = country_code
    config["proxy"] = ""
    network_save_config(config)
    print(_("Selected HTTP Proxy location") + ": " + country_code + " - " + country_name)

    if config.get("proxy_enabled"):
        network_enable_http_proxy(force_refresh=True)


def network_renew_proxy_pool():
    config = network_load_config()
    country = config.get("country", "US")
    if config.get("proxy_enabled"):
        network_enable_http_proxy(force_refresh=True)
        return

    # Refresh the pool without turning HTTP Proxy on when the user has HTTP Proxy disabled.
    pool = network_fetch_proxy_pool(country, force_refresh=True)
    print(str(len(pool)) + " proxies cached for " + country + ".")
    print(_("HTTP Proxy is disabled. Proxies were refreshed but no proxy was activated."))


def network_renew_tools_and_connections():
    network_update_tools(silent=False)
    config = network_load_config()
    if config.get("tor_enabled"):
        ok, msg = network_start_tor(silent=False)
        print(msg)
    if config.get("proxy_enabled"):
        network_enable_http_proxy(force_refresh=True)
    else:
        # Refresh the currently selected country pool even if HTTP Proxy is off.
        country = config.get("country", "US")
        pool = network_fetch_proxy_pool(country, force_refresh=True)
        print(str(len(pool)) + " proxies cached for " + country + ".")
    network_apply_bashrc_exports()


def network_autostart_if_enabled(silent=True):
    config = network_load_config()
    changed = False
    if config.get("tor_enabled"):
        network_start_tor(silent=silent, allow_install=not silent)
        changed = True
    if config.get("proxy_enabled"):
        country = config.get("country", "US")
        proxy = str(config.get("proxy") or "").strip()
        if (not proxy) or network_is_proxy_marked_bad(country, proxy):
            new_proxy, _msg = network_select_working_proxy(country, force_refresh=False, silent=True)
            if new_proxy:
                config["proxy"] = new_proxy
                config["last_proxy_refresh"] = int(time.time())
                network_save_config(config)
                changed = True
        # When a saved proxy exists and is not marked bad, do not test it on startup.
    if changed or config.get("tor_enabled") or config.get("proxy_enabled"):
        network_apply_bashrc_exports()


def network_session_guard():
    """Quietly refresh HTTP Proxy/Tor support for new Termux sessions.

    This is called from bash.bashrc. It keeps the saved proxy exports current and
    restarts Tor if Tor was enabled but the process is not listening anymore. It
    does not print anything because it runs during shell startup/prompt repair.
    """
    try:
        network_autostart_if_enabled(silent=True)
        network_apply_bashrc_exports()
        return True
    except Exception:
        return False


def network_utilities_menu():
    while True:
        clear_terminal_screen()
        network_print_status()
        config = network_load_config()
        options = [
            _("Disable Tor Connection") if config.get("tor_enabled") else _("Enable Tor Connection"),
            _("Disable HTTP Proxy Connection") if config.get("proxy_enabled") else _("Enable HTTP Proxy Connection"),
            _("Choose HTTP Proxy Location"),
            _("Renew HTTP Proxy Proxies"),
            _("Update HTTP Proxy/Tor Tools"),
            _("Show HTTP Proxy/Tor Status"),
            _("Back"),
        ]
        print("")
        for index, option in enumerate(options, start=1):
            print(str(index) + ". " + option)
        choice = input("\n" + _("Enter the number of your choice: ")).strip()

        clear_terminal_screen()
        if choice == "1":
            if config.get("tor_enabled"):
                network_disable_tor()
            else:
                network_enable_tor()
        elif choice == "2":
            if config.get("proxy_enabled"):
                network_disable_http_proxy()
            else:
                network_enable_http_proxy(force_refresh=False)
        elif choice == "3":
            network_choose_proxy_location()
        elif choice == "4":
            network_renew_proxy_pool()
        elif choice == "5":
            network_renew_tools_and_connections()
        elif choice == "6":
            network_print_status()
        elif choice == "7" or choice.lower() in ("b", "back", "q", "quit"):
            break
        else:
            print(_("Invalid selection. Please try again."))
        input("\n" + _("Press Enter to continue..."))


