def ensure_required_settings_menu_items(options):
    """Keep required entries and remove legacy Ded-Guy action entries.

    Ded-Guy is a main-menu style selected through Change Menu Style. It must never
    appear as a standalone Settings action, even if an older cached option list is
    passed into this helper.
    """
    legacy_pipboy_labels = {
        "pip-boy",
        "ded guy",
        str(_("Ded-Guy")).strip().casefold(),
    }
    options[:] = [
        item for item in options
        if str(item).strip().casefold() not in legacy_pipboy_labels
    ]

    sponsors_label = _("Access Sponsors-Only Scripts")
    if sponsors_label not in options:
        try:
            update_packages_index = options.index(_("Update Packages & Modules"))
            options.insert(update_packages_index + 1, sponsors_label)
        except ValueError:
            options.insert(4, sponsors_label)
    return options

def get_settings_options():
    options = [
        _("About"),
        _("DedSec Project Update (Source 1)"),
        _("DedSec Project Update (Source 2)"),
        _("Update Packages & Modules"),
        _("Access Sponsors-Only Scripts"),
        _("Save DedSec Project"),
        _("Transfer System"),
        _("Change Prompt"),
        _("GitHub Account"),
        _("Termux Usage Stats"),
        _("HTTP Proxy & Tor Utilities"),
        _("Change Menu Style"),
        get_menu_autostart_label(),
        _("Choose Language/Επιλέξτε Γλώσσα"),
        _("Credits"),
        _("Uninstall DedSec Project"),
        _("Exit")
    ]
    return ensure_required_settings_menu_items(options)


def run_settings_list_menu():
    """Settings menu using list style (curses)"""
    def menu(stdscr):
        curses.curs_set(0)
        curses.start_color()
        curses.use_default_colors()
        menu_options = get_settings_options()
        current_row = 0
        while True:
            stdscr.clear()
            height, width = stdscr.getmaxyx()
            title = _("Select an option")
            safe_curses_addstr(stdscr, 1, width // 2 - len(title) // 2, title)
            for idx, option in enumerate(menu_options):
                x = width // 2 - len(option) // 2
                y = height // 2 - len(menu_options) // 2 + idx
                if idx == current_row:
                    stdscr.attron(curses.A_REVERSE)
                    safe_curses_addstr(stdscr, y, x, option)
                    stdscr.attroff(curses.A_REVERSE)
                else:
                    safe_curses_addstr(stdscr, y, x, option)
            stdscr.refresh()
            key = stdscr.getch()
            if key == curses.KEY_UP and current_row > 0:
                current_row -= 1
            elif key == curses.KEY_DOWN and current_row < len(menu_options) - 1:
                current_row += 1
            elif key in [curses.KEY_ENTER, 10, 13]:
                return current_row
            elif key in [ord('q'), ord('Q')]:
                return None
    
    return safe_curses_wrapper(menu)

def run_settings_grid_menu():
    """Settings menu using grid style"""
    def draw_settings_grid_menu(stdscr, options):
        curses.curs_set(0)
        stdscr.nodelay(0)
        stdscr.timeout(-1)
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_BLACK, curses.COLOR_WHITE)
        curses.init_pair(2, curses.COLOR_MAGENTA, -1)
        curses.init_pair(3, curses.COLOR_WHITE, -1)
        
        current_index = 0
        num_items = len(options)
        
        while True:
            stdscr.clear()
            term_height, term_width = stdscr.getmaxyx()
            
            # Grid layout parameters
            ICON_WIDTH = max(25, term_width // 3)
            ICON_HEIGHT = max(5, term_height // 5)
            max_cols = term_width // ICON_WIDTH
            
            if max_cols == 0:
                ICON_WIDTH = term_width
                max_cols = 1
            
            rows_per_page = (term_height - 2) // ICON_HEIGHT
            total_visible_cells = max_cols * rows_per_page
            
            if total_visible_cells <= 0:
                safe_curses_addstr(stdscr, 0, 0, _("Terminal window is too small."))
                stdscr.refresh()
                key = stdscr.getch()
                if key in [ord('q'), ord('Q'), 10, 13]:
                    return None
                continue

            # Draw title
            title = _("Select an option")
            try:
                safe_curses_addstr(stdscr, 0, term_width // 2 - len(title) // 2, title, curses.color_pair(3))
            except curses.error:
                pass

            page_start_index = (current_index // total_visible_cells) * total_visible_cells
            page_end_index = min(page_start_index + total_visible_cells, num_items)
            
            # Draw grid items
            for idx_on_page, actual_index in enumerate(range(page_start_index, page_end_index)):
                i = idx_on_page // max_cols
                j = idx_on_page % max_cols
                y = 2 + i * ICON_HEIGHT
                x = j * ICON_WIDTH
                
                if y + ICON_HEIGHT >= term_height - 1:
                    continue

                # Draw box
                for box_i in range(x, x + ICON_WIDTH):
                    if box_i < term_width:
                        try:
                            stdscr.addch(y, box_i, curses.ACS_HLINE, curses.color_pair(2))
                            stdscr.addch(y + ICON_HEIGHT - 1, box_i, curses.ACS_HLINE, curses.color_pair(2))
                        except curses.error:
                            pass
                
                for box_j in range(y, y + ICON_HEIGHT):
                    if box_j < term_height - 1:
                        try:
                            stdscr.addch(box_j, x, curses.ACS_VLINE, curses.color_pair(2))
                            stdscr.addch(box_j, x + ICON_WIDTH - 1, curses.ACS_VLINE, curses.color_pair(2))
                        except curses.error:
                            pass
                
                # Draw corners
                try:
                    stdscr.addch(y, x, curses.ACS_ULCORNER, curses.color_pair(2))
                    stdscr.addch(y, x + ICON_WIDTH - 1, curses.ACS_URCORNER, curses.color_pair(2))
                    stdscr.addch(y + ICON_HEIGHT - 1, x, curses.ACS_LLCORNER, curses.color_pair(2))
                    stdscr.addch(y + ICON_HEIGHT - 1, x + ICON_WIDTH - 1, curses.ACS_LRCORNER, curses.color_pair(2))
                except curses.error:
                    pass

                # Highlight current selection
                if actual_index == current_index:
                    for hi in range(y + 1, y + ICON_HEIGHT - 1):
                        for hj in range(x + 1, x + ICON_WIDTH - 1):
                            if hi < term_height - 1 and hj < term_width - 1:
                                try:
                                    stdscr.addch(hi, hj, ' ', curses.color_pair(1))
                                except curses.error:
                                    pass

                # Draw option text
                option_text = options[actual_index]
                box_text_width = ICON_WIDTH - 4
                wrapped_lines = textwrap.wrap(option_text, box_text_width)
                
                total_lines = len(wrapped_lines)
                padding_y = (ICON_HEIGHT - total_lines) // 2
                
                for line_idx, line in enumerate(wrapped_lines):
                    line_y = y + padding_y + line_idx
                    padding_x = (ICON_WIDTH - len(line)) // 2
                    line_x = x + padding_x
                    
                    if line_y < term_height - 1 and line_x < term_width:
                        try:
                            color = curses.color_pair(1) if actual_index == current_index else curses.color_pair(3)
                            safe_curses_addstr(stdscr, line_y, line_x, line[:term_width - line_x], color)
                        except curses.error:
                            pass
            
            # Draw instructions
            instructions = "Arrow Keys: Move | Enter: Select | q: Quit"
            try:
                safe_curses_addstr(stdscr, term_height - 1, 0, instructions[:term_width - 1], curses.color_pair(3))
            except curses.error:
                pass
            
            stdscr.refresh()
            
            key = stdscr.getch()
            
            if key == curses.KEY_UP and current_index - max_cols >= 0:
                current_index -= max_cols
            elif key == curses.KEY_DOWN and current_index + max_cols < num_items:
                current_index += max_cols
            elif key == curses.KEY_LEFT and current_index % max_cols > 0:
                current_index -= 1
            elif key == curses.KEY_RIGHT and (current_index % max_cols) < (max_cols - 1) and (current_index + 1) < num_items:
                current_index += 1
            elif key in [10, 13]:
                return current_index
            elif key in [ord('q'), ord('Q')]:
                return None
            elif key == curses.KEY_RESIZE:
                pass

    menu_options = get_settings_options()
    
    return safe_curses_wrapper(lambda stdscr: draw_settings_grid_menu(stdscr, menu_options))

def run_settings_number_menu():
    """Settings menu using number style"""
    menu_options = get_settings_options()
    
    while True:
        clear_terminal_screen()
        print(f"=== {_('Select an option')} ===\n")
        for i, option in enumerate(menu_options):
            print(f"{i + 1}. {option}")
        print(f"\n0. {_('Exit')}")
        
        try:
            choice_str = input(f"\n{_('Enter the number of your choice: ')}").strip()
            if not choice_str:
                continue
            choice = int(choice_str)
        except ValueError:
            print(_("Invalid selection. Please try again."))
            input(_("Press Enter to continue..."))
            continue
        
        if choice == 0:
            return len(menu_options) - 1  # Exit option
        
        if 1 <= choice <= len(menu_options):
            return choice - 1
        else:
            print(_("Invalid selection. Please try again."))
            input(_("Press Enter to continue..."))

def run_settings_menu():
    """Main settings menu that uses the current menu style"""
    current_style = get_current_menu_style()
    
    if current_style == 'grid':
        selected = run_settings_grid_menu()
    elif current_style == 'number':
        selected = run_settings_number_menu()
    else:  # Default to list
        selected = run_settings_list_menu()
    
    return selected



def _pipboy_impl_pipboy_expert_self_test_1():
    checks = []
    def record(name, condition, detail=""):
        checks.append((name, bool(condition), str(detail or "")))
    try:
        payload = pipboy_embedded_project_payload()
        record("Embedded complete uploaded project", len(payload.get("files", {})) == 201, len(payload.get("files", {})))
        record("Embedded script coverage", int(payload.get("counts", {}).get("scripts", 0)) >= 180, payload.get("counts", {}).get("scripts"))
    except Exception as exc:
        record("Embedded complete uploaded project", False, exc)
    try:
        catalog = pipboy_tool_catalog_payload()
        record("Authoritative README tool catalog", len(catalog) >= 80, len(catalog))
        record("Pet Friends catalog knowledge", "pet friends" in catalog)
        record("Termux Repair catalog knowledge", "termux repair wizard" in catalog)
    except Exception as exc:
        record("Authoritative README tool catalog", False, exc)
    try:
        index = pipboy_load_project_index(auto_build=False)
        record("Merged project knowledge", len(index.get("files", {})) >= 201, len(index.get("files", {})))
        pet = pipboy_search_project("Pet Friends virtual pet save", limit=4)
        record("Hybrid project retrieval", bool(pet) and "pet friends" in pipboy_normalize(pet[0].get("name")), pet[0].get("name") if pet else "none")
    except Exception as exc:
        record("Hybrid project retrieval", False, exc)
    state = {"config": pipboy_load_config(), "last_matches": [], "inventory": pipboy_empty_inventory(), "cwd": HOME_DIR}
    try:
        answer, _ = pipboy_intelligence_answer("where does Pet Friends save its data?", state)
        record("Direct save-path reasoning", "petfriends_save.json" in answer, answer[:180])
    except Exception as exc:
        record("Direct save-path reasoning", False, exc)
    try:
        answer, matches = pipboy_intelligence_answer("which tool repairs broken Termux scripts and dependencies?", state)
        record("Project tool recommendation", bool(matches) and "repair wizard" in pipboy_normalize(matches[0].get("name")), matches[0].get("name") if matches else answer[:120])
    except Exception as exc:
        record("Project tool recommendation", False, exc)
    try:
        answer, _ = pipboy_intelligence_answer("trace function get_existing_sponsors_paths", state)
        record("Code-symbol tracing", "get_existing_sponsors_paths" in answer and "Settings.py" in answer, answer[:180])
    except Exception as exc:
        record("Code-symbol tracing", False, exc)
    try:
        clone = pipboy_clone_action("https://github.com/example/example.git")
        shell = pipboy_shell_action("pkg install git")
        record("Confirmed Git clone safety", bool(clone.get("risky")))
        record("Confirmed shell safety", bool(shell.get("risky")))
    except Exception as exc:
        record("Confirmed action safety", False, exc)
    config = pipboy_load_config()
    record("Maximum single-file defaults", config.get("intelligence_depth") in {"balanced", "deep", "expert"} and config.get("intelligence_detail") in {"detailed", "maximum"} and int(config.get("intelligence_max_sources", 0)) >= 6)
    print("Ded-Guy single-file expert self-test")
    print("=" * 52)
    for name, passed, detail in checks:
        print(f"[{'PASS' if passed else 'FAIL'}] {name}" + (f": {detail}" if detail and not passed else ""))
    failures = [item for item in checks if not item[1]]
    print("=" * 52)
    print("RESULT: " + ("PASS" if not failures else "FAIL"))
    return not failures

def main():
    while True:
        should_exit = False
        pause_without_text = False

        selected = run_settings_menu()
        if selected is None:
            print(_("Exiting..."))
            break

        clear_terminal_screen()
        if selected == 0:
            show_about()
        elif selected == 1:
            update_dedsec_source_1()
        elif selected == 2:
            update_dedsec_source_2()
        elif selected == 3:
            update_packages_modules()
        elif selected == 4:
            access_sponsors_only_scripts()
        elif selected == 5:
            save_project()
            pause_without_text = True
        elif selected == 6:
            create_termux_transfer()
            pause_without_text = True
        elif selected == 7:
            change_prompt()
        elif selected == 8:
            github_account_menu()
        elif selected == 9:
            show_termux_usage_stats()
        elif selected == 10:
            network_utilities_menu()
        elif selected == 11:
            change_menu_style()
        elif selected == 12:
            toggle_menu_autostart()
        elif selected == 13:
            change_language()
        elif selected == 14:
            show_credits()
        elif selected == 15:
            should_exit = uninstall_dedsec()
            if should_exit:
                break
        elif selected == 16:
            print(_("Exiting..."))
            break

        if not should_exit:
            if pause_without_text:
                input()
            else:
                input(f"\n{_('Press Enter to return to the settings menu...')}")


